INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_cucumber-tomato-salad','cucumber-tomato-salad','{"image":"/recipe-covers/cucumber-tomato-salad.webp","originalCard":"/recipe-cards/cucumber-tomato-card.webp","date":"2024-12-27","translations":{"en":{"title":"Cucumber Tomato Salad","category":"Fresh sides","excerpt":"A refreshing, nutrient-packed cucumber and tomato salad with herbs and a light vinaigrette.","tags":["Side","Low Carb","Quick"],"prepTime":"15 min","cookTime":"0 min","servings":"4 portions","diabetesNote":"Fresh vegetables add crunch, volume, and hydration without a large glucose load.","carbAwareness":"Pair with protein and a planned carbohydrate portion for a complete meal.","ingredients":["10 oz cherry tomatoes, halved","1 English cucumber","1/2 small red onion, thinly sliced","2 tbsp oil","2 tbsp red wine vinegar or white wine vinegar","1/2 teaspoon salt","1/4 teaspoon black pepper","1 tbsp chopped fresh or dried parsley","1 tsp honey, optional"],"instructions":["Trim the cucumber ends, halve lengthwise, then slice into 1/4-inch half rounds.","Place cucumber, tomatoes, and sliced red onion in a medium bowl.","Whisk oil, vinegar, honey, salt, and pepper.","Pour dressing over the salad and toss gently.","Stir in herbs if using. Serve immediately or chill for one to two hours."],"nutrition":["Calories not listed","Rich in vitamins A and C","Hydrating vegetables"]},"zh-CN":{"title":"黄瓜番茄沙拉","category":"清爽配菜","excerpt":"清爽且营养丰富的黄瓜番茄沙拉，搭配香草和清淡油醋汁。","tags":["配菜","低碳水","快速"],"prepTime":"15 分钟","cookTime":"0 分钟","servings":"4 份","diabetesNote":"新鲜蔬菜带来脆感、体积和水分，同时不会造成很大的血糖负荷。","carbAwareness":"搭配蛋白质和计划好的碳水份量，可组成完整一餐。","ingredients":["约 280 克樱桃番茄，对半切","1 根英式黄瓜","1/2 个小红洋葱，薄切","2 汤匙油","2 汤匙红酒醋或白酒醋","1/2 茶匙盐","1/4 茶匙黑胡椒","1 汤匙新鲜或干欧芹，切碎","1 茶匙蜂蜜，可选"],"instructions":["切去黄瓜两端，纵向对半切，再切成约 0.6 厘米厚的半圆片。","将黄瓜、番茄和红洋葱放入中碗。","搅匀油、醋、蜂蜜、盐和胡椒。","把酱汁淋在沙拉上，轻轻拌匀。","如使用香草，最后拌入。可立即食用，也可冷藏一到两小时。"],"nutrition":["未列出热量","富含维生素 A 和 C","补水型蔬菜"]},"zh-TW":{"title":"黃瓜番茄沙拉","category":"清爽配菜","excerpt":"清爽且營養豐富的黃瓜番茄沙拉，搭配香草和清淡油醋汁。","tags":["配菜","低碳水","快速"],"prepTime":"15 分鐘","cookTime":"0 分鐘","servings":"4 份","diabetesNote":"新鮮蔬菜帶來脆感、體積和水分，同時不會造成很大的血糖負荷。","carbAwareness":"搭配蛋白質和計劃好的碳水份量，可組成完整一餐。","ingredients":["約 280 克櫻桃番茄，對半切","1 根英式黃瓜","1/2 個小紅洋蔥，薄切","2 湯匙油","2 湯匙紅酒醋或白酒醋","1/2 茶匙鹽","1/4 茶匙黑胡椒","1 湯匙新鮮或幹歐芹，切碎","1 茶匙蜂蜜，可選"],"instructions":["切去黃瓜兩端，縱向對半切，再切成約 0.6 釐米厚的半圓片。","將黃瓜、番茄和紅洋蔥放入中碗。","攪勻油、醋、蜂蜜、鹽和胡椒。","把醬汁淋在沙拉上，輕輕拌勻。","如使用香草，最後拌入。可立即食用，也可冷藏一到兩小時。"],"nutrition":["未列出熱量","富含維生素 A 和 C","補水型蔬菜"]},"es":{"title":"Ensalada de pepino y tomate","category":"Acompañamientos frescos","excerpt":"Una ensalada refrescante y nutritiva de pepino y tomate con hierbas y una vinagreta ligera.","tags":["Acompañamiento","Baja en carbohidratos","Rápida"],"prepTime":"15 min","cookTime":"0 min","servings":"4 porciones","diabetesNote":"Las verduras frescas aportan textura, volumen e hidratación sin una carga alta de glucosa.","carbAwareness":"Acompáñela con proteína y una porción planificada de carbohidratos para una comida completa.","ingredients":["10 oz de tomates cherry, cortados por la mitad","1 pepino inglés","1/2 cebolla morada pequeña, en rebanadas finas","2 cucharadas de aceite","2 cucharadas de vinagre de vino tinto o vinagre de vino blanco","1/2 cucharadita de sal","1/4 cucharadita de pimienta negra","1 cucharada de perejil fresco picado o seco","1 cucharadita de miel, opcional"],"instructions":["Corte los extremos del pepino, pártalo a lo largo por la mitad y luego córtelo en medias lunas de 1/4 de pulgada.","Coloque el pepino, los tomates y la cebolla morada en un tazón mediano.","Bata el aceite, el vinagre, la miel, la sal y la pimienta.","Vierta el aderezo sobre la ensalada y mezcle suavemente.","Agregue las hierbas si las usa. Sirva de inmediato o refrigere de una a dos horas."],"nutrition":["Calorías no indicadas","Rica en vitaminas A y C","Verduras hidratantes"]}}}','{"image":"/recipe-covers/cucumber-tomato-salad.webp","originalCard":"/recipe-cards/cucumber-tomato-card.webp","date":"2024-12-27","translations":{"en":{"title":"Cucumber Tomato Salad","category":"Fresh sides","excerpt":"A refreshing, nutrient-packed cucumber and tomato salad with herbs and a light vinaigrette.","tags":["Side","Low Carb","Quick"],"prepTime":"15 min","cookTime":"0 min","servings":"4 portions","diabetesNote":"Fresh vegetables add crunch, volume, and hydration without a large glucose load.","carbAwareness":"Pair with protein and a planned carbohydrate portion for a complete meal.","ingredients":["10 oz cherry tomatoes, halved","1 English cucumber","1/2 small red onion, thinly sliced","2 tbsp oil","2 tbsp red wine vinegar or white wine vinegar","1/2 teaspoon salt","1/4 teaspoon black pepper","1 tbsp chopped fresh or dried parsley","1 tsp honey, optional"],"instructions":["Trim the cucumber ends, halve lengthwise, then slice into 1/4-inch half rounds.","Place cucumber, tomatoes, and sliced red onion in a medium bowl.","Whisk oil, vinegar, honey, salt, and pepper.","Pour dressing over the salad and toss gently.","Stir in herbs if using. Serve immediately or chill for one to two hours."],"nutrition":["Calories not listed","Rich in vitamins A and C","Hydrating vegetables"]},"zh-CN":{"title":"黄瓜番茄沙拉","category":"清爽配菜","excerpt":"清爽且营养丰富的黄瓜番茄沙拉，搭配香草和清淡油醋汁。","tags":["配菜","低碳水","快速"],"prepTime":"15 分钟","cookTime":"0 分钟","servings":"4 份","diabetesNote":"新鲜蔬菜带来脆感、体积和水分，同时不会造成很大的血糖负荷。","carbAwareness":"搭配蛋白质和计划好的碳水份量，可组成完整一餐。","ingredients":["约 280 克樱桃番茄，对半切","1 根英式黄瓜","1/2 个小红洋葱，薄切","2 汤匙油","2 汤匙红酒醋或白酒醋","1/2 茶匙盐","1/4 茶匙黑胡椒","1 汤匙新鲜或干欧芹，切碎","1 茶匙蜂蜜，可选"],"instructions":["切去黄瓜两端，纵向对半切，再切成约 0.6 厘米厚的半圆片。","将黄瓜、番茄和红洋葱放入中碗。","搅匀油、醋、蜂蜜、盐和胡椒。","把酱汁淋在沙拉上，轻轻拌匀。","如使用香草，最后拌入。可立即食用，也可冷藏一到两小时。"],"nutrition":["未列出热量","富含维生素 A 和 C","补水型蔬菜"]},"zh-TW":{"title":"黃瓜番茄沙拉","category":"清爽配菜","excerpt":"清爽且營養豐富的黃瓜番茄沙拉，搭配香草和清淡油醋汁。","tags":["配菜","低碳水","快速"],"prepTime":"15 分鐘","cookTime":"0 分鐘","servings":"4 份","diabetesNote":"新鮮蔬菜帶來脆感、體積和水分，同時不會造成很大的血糖負荷。","carbAwareness":"搭配蛋白質和計劃好的碳水份量，可組成完整一餐。","ingredients":["約 280 克櫻桃番茄，對半切","1 根英式黃瓜","1/2 個小紅洋蔥，薄切","2 湯匙油","2 湯匙紅酒醋或白酒醋","1/2 茶匙鹽","1/4 茶匙黑胡椒","1 湯匙新鮮或幹歐芹，切碎","1 茶匙蜂蜜，可選"],"instructions":["切去黃瓜兩端，縱向對半切，再切成約 0.6 釐米厚的半圓片。","將黃瓜、番茄和紅洋蔥放入中碗。","攪勻油、醋、蜂蜜、鹽和胡椒。","把醬汁淋在沙拉上，輕輕拌勻。","如使用香草，最後拌入。可立即食用，也可冷藏一到兩小時。"],"nutrition":["未列出熱量","富含維生素 A 和 C","補水型蔬菜"]},"es":{"title":"Ensalada de pepino y tomate","category":"Acompañamientos frescos","excerpt":"Una ensalada refrescante y nutritiva de pepino y tomate con hierbas y una vinagreta ligera.","tags":["Acompañamiento","Baja en carbohidratos","Rápida"],"prepTime":"15 min","cookTime":"0 min","servings":"4 porciones","diabetesNote":"Las verduras frescas aportan textura, volumen e hidratación sin una carga alta de glucosa.","carbAwareness":"Acompáñela con proteína y una porción planificada de carbohidratos para una comida completa.","ingredients":["10 oz de tomates cherry, cortados por la mitad","1 pepino inglés","1/2 cebolla morada pequeña, en rebanadas finas","2 cucharadas de aceite","2 cucharadas de vinagre de vino tinto o vinagre de vino blanco","1/2 cucharadita de sal","1/4 cucharadita de pimienta negra","1 cucharada de perejil fresco picado o seco","1 cucharadita de miel, opcional"],"instructions":["Corte los extremos del pepino, pártalo a lo largo por la mitad y luego córtelo en medias lunas de 1/4 de pulgada.","Coloque el pepino, los tomates y la cebolla morada en un tazón mediano.","Bata el aceite, el vinagre, la miel, la sal y la pimienta.","Vierta el aderezo sobre la ensalada y mezcle suavemente.","Agregue las hierbas si las usa. Sirva de inmediato o refrigere de una a dos horas."],"nutrition":["Calorías no indicadas","Rica en vitaminas A y C","Verduras hidratantes"]}}}','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_cottage-cheese-blueberries-hemp-seeds','cottage-cheese-blueberries-hemp-seeds','{"image":"/recipe-covers/cottage-cheese-blueberries.webp","originalCard":"/recipe-cards/cottage-cheese-blueberries-card.webp","date":"2024-12-29","translations":{"en":{"title":"Cottage Cheese with Blueberries and Hemp Seeds","category":"High-protein snack","excerpt":"A high-protein, nutrient-dense snack with berries, antioxidants, and healthy fats.","tags":["Breakfast","High Protein","Quick"],"prepTime":"5 min","cookTime":"0 min","servings":"2","diabetesNote":"Protein from cottage cheese and fiber from berries can support steadier morning energy.","carbAwareness":"Keep fruit portions intentional and pair with protein or fat.","ingredients":["2 cup cottage cheese, whole-milk","1/2 cup blueberries","1/4 cup hemp seeds"],"instructions":["Add cottage cheese to serving cups.","Top with blueberries and hemp seeds.","Optional toppings include raspberries, strawberries, walnuts, almonds, ground flax, and pumpkin seeds."],"nutrition":["Nutrition not listed on original card","High-protein","Contains dairy and hemp seeds"]},"zh-CN":{"title":"茅屋奶酪配蓝莓和大麻籽","category":"高蛋白点心","excerpt":"高蛋白、营养密度高的点心，含浆果、抗氧化成分和健康脂肪。","tags":["早餐","高蛋白","快速"],"prepTime":"5 分钟","cookTime":"0 分钟","servings":"2","diabetesNote":"茅屋奶酪提供蛋白质，浆果提供纤维，有助于支持更稳定的早晨能量。","carbAwareness":"水果份量要有计划，并搭配蛋白质或脂肪。","ingredients":["2 杯全脂茅屋奶酪","1/2 杯蓝莓","1/4 杯大麻籽"],"instructions":["将茅屋奶酪放入食用杯。","上面加入蓝莓和大麻籽。","可选配料包括覆盆子、草莓、核桃、杏仁、亚麻籽粉和南瓜籽。"],"nutrition":["原始卡片未列营养数据","高蛋白","含乳制品和大麻籽"]},"zh-TW":{"title":"茅屋奶酪配藍莓和大麻籽","category":"高蛋白點心","excerpt":"高蛋白、營養密度高的點心，含漿果、抗氧化成分和健康脂肪。","tags":["早餐","高蛋白","快速"],"prepTime":"5 分鐘","cookTime":"0 分鐘","servings":"2","diabetesNote":"茅屋奶酪提供蛋白質，漿果提供纖維，有助於支持更穩定的早晨能量。","carbAwareness":"水果份量要有計劃，並搭配蛋白質或脂肪。","ingredients":["2 杯全脂茅屋奶酪","1/2 杯藍莓","1/4 杯大麻籽"],"instructions":["將茅屋奶酪放入食用杯。","上面加入藍莓和大麻籽。","可選配料包括覆盆子、草莓、核桃、杏仁、亞麻籽粉和南瓜籽。"],"nutrition":["原始卡片未列營養數據","高蛋白","含乳製品和大麻籽"]},"es":{"title":"Cottage cheese con arándanos y semillas de cáñamo","category":"Merienda alta en proteína","excerpt":"Una merienda alta en proteína y rica en nutrientes, con bayas, antioxidantes y grasas saludables.","tags":["Desayuno","Alta en proteína","Rápida"],"prepTime":"5 min","cookTime":"0 min","servings":"2","diabetesNote":"La proteína del cottage cheese y la fibra de las bayas pueden apoyar una energía matutina más estable.","carbAwareness":"Mantenga porciones intencionales de fruta y combínelas con proteína o grasa.","ingredients":["2 tazas de cottage cheese de leche entera","1/2 taza de arándanos","1/4 taza de semillas de cáñamo"],"instructions":["Coloque el cottage cheese en vasos o recipientes para servir.","Cubra con arándanos y semillas de cáñamo.","Los toppings opcionales incluyen frambuesas, fresas, nueces, almendras, linaza molida y semillas de calabaza."],"nutrition":["La nutrición no aparece en la tarjeta original","Alta en proteína","Contiene lácteos y semillas de cáñamo"]}}}','{"image":"/recipe-covers/cottage-cheese-blueberries.webp","originalCard":"/recipe-cards/cottage-cheese-blueberries-card.webp","date":"2024-12-29","translations":{"en":{"title":"Cottage Cheese with Blueberries and Hemp Seeds","category":"High-protein snack","excerpt":"A high-protein, nutrient-dense snack with berries, antioxidants, and healthy fats.","tags":["Breakfast","High Protein","Quick"],"prepTime":"5 min","cookTime":"0 min","servings":"2","diabetesNote":"Protein from cottage cheese and fiber from berries can support steadier morning energy.","carbAwareness":"Keep fruit portions intentional and pair with protein or fat.","ingredients":["2 cup cottage cheese, whole-milk","1/2 cup blueberries","1/4 cup hemp seeds"],"instructions":["Add cottage cheese to serving cups.","Top with blueberries and hemp seeds.","Optional toppings include raspberries, strawberries, walnuts, almonds, ground flax, and pumpkin seeds."],"nutrition":["Nutrition not listed on original card","High-protein","Contains dairy and hemp seeds"]},"zh-CN":{"title":"茅屋奶酪配蓝莓和大麻籽","category":"高蛋白点心","excerpt":"高蛋白、营养密度高的点心，含浆果、抗氧化成分和健康脂肪。","tags":["早餐","高蛋白","快速"],"prepTime":"5 分钟","cookTime":"0 分钟","servings":"2","diabetesNote":"茅屋奶酪提供蛋白质，浆果提供纤维，有助于支持更稳定的早晨能量。","carbAwareness":"水果份量要有计划，并搭配蛋白质或脂肪。","ingredients":["2 杯全脂茅屋奶酪","1/2 杯蓝莓","1/4 杯大麻籽"],"instructions":["将茅屋奶酪放入食用杯。","上面加入蓝莓和大麻籽。","可选配料包括覆盆子、草莓、核桃、杏仁、亚麻籽粉和南瓜籽。"],"nutrition":["原始卡片未列营养数据","高蛋白","含乳制品和大麻籽"]},"zh-TW":{"title":"茅屋奶酪配藍莓和大麻籽","category":"高蛋白點心","excerpt":"高蛋白、營養密度高的點心，含漿果、抗氧化成分和健康脂肪。","tags":["早餐","高蛋白","快速"],"prepTime":"5 分鐘","cookTime":"0 分鐘","servings":"2","diabetesNote":"茅屋奶酪提供蛋白質，漿果提供纖維，有助於支持更穩定的早晨能量。","carbAwareness":"水果份量要有計劃，並搭配蛋白質或脂肪。","ingredients":["2 杯全脂茅屋奶酪","1/2 杯藍莓","1/4 杯大麻籽"],"instructions":["將茅屋奶酪放入食用杯。","上面加入藍莓和大麻籽。","可選配料包括覆盆子、草莓、核桃、杏仁、亞麻籽粉和南瓜籽。"],"nutrition":["原始卡片未列營養數據","高蛋白","含乳製品和大麻籽"]},"es":{"title":"Cottage cheese con arándanos y semillas de cáñamo","category":"Merienda alta en proteína","excerpt":"Una merienda alta en proteína y rica en nutrientes, con bayas, antioxidantes y grasas saludables.","tags":["Desayuno","Alta en proteína","Rápida"],"prepTime":"5 min","cookTime":"0 min","servings":"2","diabetesNote":"La proteína del cottage cheese y la fibra de las bayas pueden apoyar una energía matutina más estable.","carbAwareness":"Mantenga porciones intencionales de fruta y combínelas con proteína o grasa.","ingredients":["2 tazas de cottage cheese de leche entera","1/2 taza de arándanos","1/4 taza de semillas de cáñamo"],"instructions":["Coloque el cottage cheese en vasos o recipientes para servir.","Cubra con arándanos y semillas de cáñamo.","Los toppings opcionales incluyen frambuesas, fresas, nueces, almendras, linaza molida y semillas de calabaza."],"nutrition":["La nutrición no aparece en la tarjeta original","Alta en proteína","Contiene lácteos y semillas de cáñamo"]}}}','2026-10-28T00:00:0