INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_bolognese-spaghetti-squash','bolognese-spaghetti-squash','{"image":"/recipe-covers/bolognese-spaghetti-squash.webp","originalCard":"/recipe-cards/bolognese-spaghetti-squash-card.webp","date":"2025-01-06","translations":{"en":{"title":"Bolognese with Spaghetti Squash","category":"Balanced dinner","excerpt":"A low-carb, fiber-rich twist on classic Italian bolognese using spaghetti squash.","tags":["Dinner","Lower Carb","Comfort"],"prepTime":"30 min","cookTime":"15 min","servings":"4","diabetesNote":"Spaghetti squash can lower refined carbohydrate load while keeping a familiar meal format.","carbAwareness":"Add a measured whole-grain side if your meal plan needs more carbohydrates.","ingredients":["2 lb spaghetti squash","4 scallions, chopped","3 cloves garlic, minced or pressed","1 lb ground beef","3 oz pancetta","1 tsp dried oregano","1 cup canned chopped tomatoes","1 cup full-fat mozzarella cheese, crumbled","Salt, to taste","Black pepper, to taste"],"instructions":["Preheat oven to 400 F. Pierce spaghetti squash and roast 30-40 minutes until tender.","Cut squash in half, remove seeds, and pull flesh apart into spaghetti-like strands.","Saute pancetta and beef until cooked through, then remove and set aside.","Saute scallions, garlic, and oregano until fragrant.","Add beef mixture and chopped tomatoes; simmer for 15 minutes.","Season with salt and pepper.","Plate spaghetti squash and top with sauce, cheese, and fresh herbs if desired."],"nutrition":["697 calories","10g carbohydrates","55g total fat","2g fiber","38g protein"]},"zh-CN":{"title":"博洛尼亚肉酱配意面瓜","category":"均衡晚餐","excerpt":"用意面瓜替代传统意面，为经典意式肉酱带来低碳水、高纤维变化。","tags":["晚餐","较低碳水","舒心餐"],"prepTime":"30 分钟","cookTime":"15 分钟","servings":"4","diabetesNote":"意面瓜可降低精制碳水负荷，同时保留熟悉的餐食形式。","carbAwareness":"如果您的餐食计划需要更多碳水，可加入定量全谷物配菜。","ingredients":["约 900 克意面瓜","4 根青葱，切碎","3 瓣大蒜，切末或压碎","约 450 克牛绞肉","约 85 克意式培根","1 茶匙干牛至","1 杯罐装切碎番茄","1 杯全脂马苏里拉奶酪，掰碎","盐，适量","黑胡椒，适量"],"instructions":["烤箱预热至约 200 摄氏度。刺破意面瓜，烤 30-40 分钟至变软。","将意面瓜切半，去籽，用叉子把瓜肉刮成类似意面的细丝。","煎炒意式培根和牛肉至熟透，盛出备用。","炒青葱、大蒜和牛至至香味释放。","加入牛肉混合物和切碎番茄，小火炖 15 分钟。","用盐和黑胡椒调味。","将意面瓜装盘，淋上肉酱，按喜好加奶酪和新鲜香草。"],"nutrition":["697 千卡","10 克碳水化合物","55 克总脂肪","2 克纤维","38 克蛋白质"]},"zh-TW":{"title":"博洛尼亞肉醬配意麪瓜","category":"均衡晚餐","excerpt":"用意麪瓜替代傳統意麪，爲經典意式肉醬帶來低碳水、高纖維變化。","tags":["晚餐","較低碳水","舒心餐"],"prepTime":"30 分鐘","cookTime":"15 分鐘","servings":"4","diabetesNote":"意麪瓜可降低精製碳水負荷，同時保留熟悉的餐食形式。","carbAwareness":"如果您的餐食計劃需要更多碳水，可加入定量全穀物配菜。","ingredients":["約 900 剋意面瓜","4 根青蔥，切碎","3 瓣大蒜，切末或壓碎","約 450 克牛絞肉","約 85 剋意式培根","1 茶匙幹牛至","1 杯罐裝切碎番茄","1 杯全脂馬蘇裏拉奶酪，掰碎","鹽，適量","黑胡椒，適量"],"instructions":["烤箱預熱至約 200 攝氏度。刺破意麪瓜，烤 30-40 分鐘至變軟。","將意麪瓜切半，去籽，用叉子把瓜肉刮成類似意麪的細絲。","煎炒意式培根和牛肉至熟透，盛出備用。","炒青蔥、大蒜和牛至至香味釋放。","加入牛肉混合物和切碎番茄，小火燉 15 分鐘。","用鹽和黑胡椒調味。","將意麪瓜裝盤，淋上肉醬，按喜好加奶酪和新鮮香草。"],"nutrition":["697 千卡","10 克碳水化合物","55 克總脂肪","2 克纖維","38 克蛋白質"]},"es":{"title":"Boloñesa con calabaza espagueti","category":"Cena equilibrada","excerpt":"Una versión con menos carbohidratos y más fibra de la clásica boloñesa italiana, usando calabaza espagueti.","tags":["Cena","Menos carbohidratos","Reconfortante"],"prepTime":"30 min","cookTime":"15 min","servings":"4","diabetesNote":"La calabaza espagueti puede reducir la carga de carbohidratos refinados manteniendo un formato de comida familiar.","carbAwareness":"Agregue una porción medida de granos integrales si su plan de comidas requiere más carbohidratos.","ingredients":["2 lb de calabaza espagueti","4 cebollines, picados","3 dientes de ajo, picados o prensados","1 lb de carne molida de res","3 oz de pancetta","1 cucharadita de orégano seco","1 taza de tomates picados enlatados","1 taza de queso mozzarella entero, desmenuzado","Sal, al gusto","Pimienta negra, al gusto"],"instructions":["Precaliente el horno a 400 F. Perfore la calabaza espagueti y ásela de 30 a 40 minutos, hasta que esté tierna.","Corte la calabaza por la mitad, retire las semillas y separe la pulpa en hebras parecidas a espagueti.","Saltee la pancetta y la carne hasta que estén bien cocidas; retire y reserve.","Saltee los cebollines, el ajo y el orégano hasta que suelten aroma.","Agregue la mezcla de carne y los tomates picados; cocine a fuego lento durante 15 minutos.","Sazone con sal y pimienta.","Sirva la calabaza espagueti en platos y cubra con la salsa, el queso y hierbas frescas si desea."],"nutrition":["697 calorías","10 g de carbohidratos","55 g de grasa total","2 g de fibra","38 g de proteína"]}}}','{"image":"/recipe-covers/bolognese-spaghetti-squash.webp","originalCard":"/recipe-cards/bolognese-spaghetti-squash-card.webp","date":"2025-01-06","translations":{"en":{"title":"Bolognese with Spaghetti Squash","category":"Balanced dinner","excerpt":"A low-carb, fiber-rich twist on classic Italian bolognese using spaghetti squash.","tags":["Dinner","Lower Carb","Comfort"],"prepTime":"30 min","cookTime":"15 min","servings":"4","diabetesNote":"Spaghetti squash can lower refined carbohydrate load while keeping a familiar meal format.","carbAwareness":"Add a measured whole-grain side if your meal plan needs more carbohydrates.","ingredients":["2 lb spaghetti squash","4 scallions, chopped","3 cloves garlic, minced or pressed","1 lb ground beef","3 oz pancetta","1 tsp dried oregano","1 cup canned chopped tomatoes","1 cup full-fat mozzarella cheese, crumbled","Salt, to taste","Black pepper, to taste"],"instructions":["Preheat oven to 400 F. Pierce spaghetti squash and roast 30-40 minutes until tender.","Cut squash in half, remove seeds, and pull flesh apart into spaghetti-like strands.","Saute pancetta and beef until cooked through, then remove and set aside.","Saute scallions, garlic, and oregano until fragrant.","Add beef mixture and chopped tomatoes; simmer for 15 minutes.","Season with salt and pepper.","Plate spaghetti squash and top with sauce, cheese, and fresh herbs if desired."],"nutrition":["697 calories","10g carbohydrates","55g total fat","2g fiber","38g protein"]},"zh-CN":{"title":"博洛尼亚肉酱配意面瓜","category":"均衡晚餐","excerpt":"用意面瓜替代传统意面，为经典意式肉酱带来低碳水、高纤维变化。","tags":["晚餐","较低碳水","舒心餐"],"prepTime":"30 分钟","cookTime":"15 分钟","servings":"4","diabetesNote":"意面瓜可降低精制碳水负荷，同时保留熟悉的餐食形式。","carbAwareness":"如果您的餐食计划需要更多碳水，可加入定量全谷物配菜。","ingredients":["约 900 克意面瓜","4 根青葱，切碎","3 瓣大蒜，切末或压碎","约 450 克牛绞肉","约 85 克意式培根","1 茶匙干牛至","1 杯罐装切碎番茄","1 杯全脂马苏里拉奶酪，掰碎","盐，适量","黑胡椒，适量"],"instructions":["烤箱预热至约 200 摄氏度。刺破意面瓜，烤 30-40 分钟至变软。","将意面瓜切半，去籽，用叉子把瓜肉刮成类似意面的细丝。","煎炒意式培根和牛肉至熟透，盛出备用。","炒青葱、大蒜和牛至至香味释放。","加入牛肉混合物和切碎番茄，小火炖 15 分钟。","用盐和黑胡椒调味。","将意面瓜装盘，淋上肉酱，按喜好加奶酪和新鲜香草。"],"nutrition":["697 千卡","10 克碳水化合物","55 克总脂肪","2 克纤维","38 克蛋白质"]},"zh-TW":{"title":"博洛尼亞肉醬配意麪瓜","category":"均衡晚餐","excerpt":"用意麪瓜替代傳統意麪，爲經典意式肉醬帶來低碳水、高纖維變化。","tags":["晚餐","較低碳水","舒心餐"],"prepTime":"30 分鐘","cookTime":"15 分鐘","servings":"4","diabetesNote":"意麪瓜可降低精製碳水負荷，同時保留熟悉的餐食形式。","carbAwareness":"如果您的餐食計劃需要更多碳水，可加入定量全穀物配菜。","ingredients":["約 900 剋意面瓜","4 根青蔥，切碎","3 瓣大蒜，切末或壓碎","約 450 克牛絞肉","約 85 剋意式培根","1 茶匙幹牛至","1 杯罐裝切碎番茄","1 杯全脂馬蘇裏拉奶酪，掰碎","鹽，適量","黑胡椒，適量"],"instructions":["烤箱預熱至約 200 攝氏度。刺破意麪瓜，烤 30-40 分鐘至變軟。","將意麪瓜切半，去籽，用叉子把瓜肉刮成類似意麪的細絲。","煎炒意式培根和牛肉至熟透，盛出備用。","炒青蔥、大蒜和牛至至香味釋放。","加入牛肉混合物和切碎番茄，小火燉 15 分鐘。","用鹽和黑胡椒調味。","將意麪瓜裝盤，淋上肉醬，按喜好加奶酪和新鮮香草。"],"nutrition":["697 千卡","10 克碳水化合物","55 克總脂肪","2 克纖維","38 克蛋白質"]},"es":{"title":"Boloñesa con calabaza espagueti","category":"Cena equilibrada","excerpt":"Una versión con menos carbohidratos y más fibra de la clásica boloñesa italiana, usando calabaza espagueti.","tags":["Cena","Menos carbohidratos","Reconfortante"],"prepTime":"30 min","cookTime":"15 min","servings":"4","diabetesNote":"La calabaza espagueti puede reducir la carga de carbohidratos refinados manteniendo un formato de comida familiar.","carbAwareness":"Agregue una porción medida de granos integrales si su plan de comidas requiere más carbohidratos.","ingredients":["2 lb de calabaza espagueti","4 cebollines, picados","3 dientes de ajo, picados o prensados","1 lb de carne molida de res","3 oz de pancetta","1 cucharadita de orégano seco","1 taza de tomates picados enlatados","1 taza de queso mozzarella entero, desmenuzado","Sal, al gusto","Pimienta negra, al gusto"],"instructions":["Precaliente el horno a 400 F. Perfore la calabaza espagueti y ásela de 30 a 40 minutos, hasta que esté tierna.","Corte la calabaza por la mitad, retire las semillas y separe la pulpa en hebras parecidas a espagueti.","Saltee la pancetta y la carne hasta que estén bien cocidas; retire y reserve.","Saltee los cebollines, el ajo y el orégano hasta que suelten aroma.","Agregue la mezcla de carne y los tomates picados; cocine a fuego lento durante 15 minutos.","Sazone con sal y pimienta.","Sirva la calabaza espagueti en platos y cubra con la salsa, el queso y hierbas frescas si desea."],"nutrition":["697 calorías","10 g de carbohidratos","55 g de grasa total","2 g de fibra","38 g de proteína"]}}}','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_chocolate-fudge-shake','chocolate-fudge-shake','{"image":"/recipe-covers/chocolate-fudge-shake.webp","originalCard":"/recipe-cards/chocolate-fudge-shake-card.webp","date":"2025-01-12","translations":{"en":{"title":"Chocolate Fudge Shake","category":"High-protein idea","excerpt":"A creamy chocolate shake made with coconut milk, cocoa, frozen zucchini, dates, almond butter, and collagen powder.","tags":["Snack","High Protein","Dessert"],"prepTime":"4 hr","cookTime":"3 min","servings":"2","diabetesNote":"Dessert-style foods can fit better when protein, fiber, and portion size are considered.","carbAwareness":"Dates count as carbohydrate; check sweetener and fruit amounts against your meal plan.","ingredients":["1 cup canned coconut milk","1 cup zucchini, chopped and frozen","1/4 cup unsweetened cocoa powder","2 medjool dates, pitted and chopped","2 tbsp almond butter","Pinch of salt","1/2 cup water, or more as needed","3 scoops unflavored and unsweetened collagen powder"],"instructions":["Chop and freeze zucchini.","Add all ingredients to a blender and process until smooth and creamy.","Add more water as needed to process."],"nutrition":["475 calories","32g carbohydrates","35g total fat","6g fiber","22g protein"]},"zh-CN":{"title":"巧克力软糖风味奶昔","category":"高蛋白灵感","excerpt":"用椰奶、可可、冷冻西葫芦、椰枣、杏仁酱和胶原蛋白粉制作的顺滑巧克力奶昔。","tags":["点心","高蛋白","甜点"],"prepTime":"4 小时","cookTime":"3 分钟","servings":"2","diabetesNote":"考虑蛋白质、纤维和份量后，甜点风味食物也可以更好地纳入饮食计划。","carbAwareness":"椰枣属于碳水来源；请根据您的餐食计划核对甜味剂和水果用量。","ingredients":["1 杯罐装椰奶","1 杯西葫芦，切块并冷冻","1/4 杯无糖可可粉","2 颗 Medjool 椰枣，去核切碎","2 汤匙杏仁酱","一小撮盐","1/2 杯水，可按需要增加","3 勺原味无糖胶原蛋白粉"],"instructions":["将西葫芦切块并冷冻。","把所有食材加入搅拌机，打至顺滑细腻。","如搅拌困难，可按需要加入更多水。"],"nutrition":["475 千卡","32 克碳水化合物","35 克总脂肪","6 克纤维","22 克蛋白质"]},"zh-TW":{"title":"巧克力軟糖風味奶昔","category":"高蛋白靈感","excerpt":"用椰奶、可可、冷凍西葫蘆、椰棗、杏仁醬和膠原蛋白粉製作的順滑巧克力奶昔。","tags":["點心","高蛋白","甜點"],"prepTime":"4 小時","cookTime":"3 分鐘","servings":"2","diabetesNote":"考慮蛋白質、纖維和份量後，甜點風味食物也可以更好地納入飲食計劃。","carbAwareness":"椰棗屬於碳水來源；請根據您的餐食計劃覈對甜味劑和水果用量。","ingredients":["1 杯罐裝椰奶","1 杯西葫蘆，切塊並冷凍","1/4 杯無糖可可粉","2 顆 Medjool 椰棗，去核切碎","2 湯匙杏仁醬","一小撮鹽","1/2 杯水，可按需要增加","3 勺原味無糖膠原蛋白粉"],"instructions":["將西葫蘆切塊並冷凍。","把所有食材加入攪拌機，打至順滑細膩。","如攪拌困難，可按需要加入更多水。"],"nutrition":["475 千卡","32 克碳水化合物","35 克總脂肪","6 克纖維","22 克蛋白質"]},"es":{"title":"Batido de chocolate tipo fudge","category":"Idea alta en proteína","excerpt":"Un batido cremoso de chocolate con leche de coco, cacao, zucchini congelado, dátiles, mantequilla de almendra y colágeno en polvo.","tags":["Merienda","Alta en proteína","Postre"],"prepTime":"4 h","cookTime":"3 min","servings":"2","diabetesNote":"Los alimentos tipo postre pueden encajar mejor cuando se consideran la proteína, la fibra y el tamaño de la porción.","carbAwareness":"Los dátiles cuentan como carbohidratos; compare la cantidad de endulzante y fruta con su plan de comidas.","ingredients":["1 taza de leche de coco enlatada","1 taza de zucchini picado y congelado","1/4 taza de cacao en polvo sin azúcar","2 dátiles Medjool, sin hueso y picados","2 cucharadas de mantequilla de almendra","Una pizca de sal","1/2 taza de agua, o más según sea necesario","3 scoops de colágeno en polvo sin sabor y sin azúcar"],"instructions":["Pique y congele el zucchini.","Agregue todos los ingredientes a una licuadora y procese hasta que quede suave y cremoso.","Agregue más agua según sea necesario para facilitar el licuado."],"nutrition":["475 calorías","32 g de carbohidratos","35 g de grasa total","6 g de fibra","22 g de proteína"]}}}','{"image":"/recipe-covers/chocolate-fudge-shake.webp","originalCard":"/recipe-cards/chocolate-fudge-shake-card.webp","date":"2025-01-12","translations":{"en":{"title":"Chocolate Fudge Shake","category":"High-protein idea","excerpt":"A creamy chocolate shake made with coconut milk, cocoa, frozen zucchini, dates, almond butter, and collagen powder.","tags":["Snack","High Protein","Dessert"],"prepTime":"4 hr","cookTime":"3 min","servings":"2","diabetesNote":"Dessert-style foods can fit better when protein, fiber, and portion size are considered.","carbAwareness":"Dates count as carbohydrate; check sweetener and fruit amounts against your meal plan.","ingredients":["1 cup canned coconut milk","1 cup zucchini, chopped and frozen","1/4 cup unsweetened cocoa powder","2 medjool dates, pitted and chopped","2 tbsp almond butter","Pinch of salt","1/2 cup water, or more as needed","3 scoops unflavored and unsweetened collagen powder"],"instructions":["Chop and freeze zucchini.","Add all ingredients to a blender and process until smooth and creamy.","Add more water as needed to process."],"nutrition":["475 calories","32g carbohydrates","35g total fat","6g fiber","22g protein"]},"zh-CN":{"title":"巧克力软糖风味奶昔","category":"高蛋白灵感","excerpt":"用椰奶、可可、冷冻西葫芦、椰枣、杏仁酱和胶原蛋白粉制作的顺滑巧克力奶昔。","tags":["点心","高蛋白","甜点"],"prepTime":"4 小时","cookTime":"3 分钟","servings":"2","diabetesNote":"考虑蛋白质、纤维和份量后，甜点风味食物也可以更好地纳入饮食计划。","carbAwareness":"椰枣属于碳水来源；请根据您的餐食计划核对甜味剂和水果用量。","ingredients":["1 杯罐装椰奶","1 杯西葫芦，切块并冷冻","1/4 杯无糖可可粉","2 颗 Medjool 椰枣，去核切碎","2 汤匙杏仁酱","一小撮盐","1/2 杯水，可按需要增加","3 勺原味无糖胶原蛋白粉"],"instructions":["将西葫芦切块并冷冻。","把所有食材加入搅拌机，打至顺滑细腻。","如搅拌困难，可按需要加入更多水。"],"nutrition":["475 千卡","32 克碳水化合物","35 克总脂肪","6 克纤维","22 克蛋白质"]},"zh-TW":{"title":"巧克力軟糖風味奶昔","category":"高蛋白靈感","excerpt":"用椰奶、可可、冷凍西葫蘆、椰棗、杏仁醬和膠原蛋白粉製作的順滑巧克力奶昔。","tags":["點心","高蛋白","甜點"],"prepTime":"4 小時","cookTime":"3 分鐘","servings":"2","diabetesNote":"考慮蛋白質、纖維和份量後，甜點風味食物也可以更好地納入飲食計劃。","carbAwareness":"椰棗屬於碳水來源；請根據您的餐食計劃覈對甜味劑和水果用量。","ingredients":["1 杯罐裝椰奶","1 杯西葫蘆，切塊並冷凍","1/4 杯無糖可可粉","2 顆 Medjool 椰棗，去核切碎","2 湯匙杏仁醬","一小撮鹽","1/2 杯水，可按需要增加","3 勺原味無糖膠原蛋白粉"],"instructions":["將西葫蘆切塊並冷凍。","把所有食材加入攪拌機，打至順滑細膩。","如攪拌困難，可按需要加入更多水。"],"nutrition":["475 千卡","32 克碳水化合物","35 克總脂肪","6 克纖維","22 克蛋白質"]},"es":{"title":"Batido de chocolate tipo fudge","category":"Idea alta en proteína","excerpt":"Un batido cremoso de chocolate con leche de coco, cacao, zucchini congelado, dátiles, mantequilla de almendra y colágeno en polvo.","tags":["Merienda","Alta en proteína","Postre"],"prepTime":"4 h","cookTime":"3 min","servings":"2","diabetesNote":"Los alimentos tipo postre pueden encajar mejor cuando se consideran la proteína, la fibra y el tamaño de la porción.","carbAwareness":"Los dátiles cuentan como carbohidratos; compare la cantidad de endulzante y fruta con su plan de comidas.","ingredients":["1 taza de leche de coco enlatada","1 taza de zucchini picado y congelado","1/4 taza de cacao en polvo sin azúcar","2 dátiles Medjool, sin hueso y picados","2 cucharadas de mantequilla de almendra","Una pizca de sal","1/2 taza de agua, o más según sea necesario","3 scoops de colágeno en polvo sin sabor y sin azúcar"],"instructions":["Pique y congele el zucchini.","Agregue todos los ingredientes a una licuadora y procese hasta que quede suave y cremoso.","Agregue más agua según sea necesario para facilitar el licuado."],"nutrition":["475 calorías","32 g de carbohidratos","35 g de grasa total","6 g de fibra","22 g de proteína"]}}}','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_high-protein-rosemary-focaccia','high-protein-rosemary-focaccia','{"image":"/recipe-covers/rosemary-focaccia.webp","originalCard":"/recipe-cards/rosemary-focaccia-card.webp","date":"2025-01-06","translations":{"en":{"title":"High-Protein Rosemary Focaccia","category":"Meal prep","excerpt":"A savory low-carb bread made with mozzarella, cream cheese, almond flour, eggs, and rosemary.","tags":["High Protein","Side","Meal Prep"],"prepTime":"10 min","cookTime":"20 min","servings":"10","diabetesNote":"Higher-protein baked options may fit better than refined bread when portions are planned.","carbAwareness":"Bread-style foods still count as carbohydrate; pair with protein and vegetables.","ingredients":["3 cup full-fat shredded mozzarella cheese","5 oz cream cheese","2 cup almond flour","1 tbsp baking powder","1 tsp garlic powder","3 eggs","2 tsp dried rosemary","1 tsp salt"],"instructions":["Preheat oven to 425 F and line a baking sheet with parchment paper.","Microwave mozzarella and cream cheese for 90 seconds, stir, then microwave again if needed until melted.","Whisk almond flour, baking powder, and garlic powder until no lumps appear.","Add eggs and melted cheese mixture; process into a dough ball.","Press dough into a flat rectangle about 1/4 inch thick.","Drizzle with olive oil and sprinkle with rosemary and salt.","Bake 10-12 minutes, checking frequently, until edges brown.","Cool briefly before cutting. Reheat in toaster oven if desired."],"nutrition":["297 calories","7g carbohydrates","25g total fat","3g fiber","15g protein"]},"zh-CN":{"title":"高蛋白迷迭香佛卡夏","category":"备餐","excerpt":"用马苏里拉奶酪、奶油奶酪、杏仁粉、鸡蛋和迷迭香制作的咸香低碳水面包。","tags":["高蛋白","配菜","备餐"],"prepTime":"10 分钟","cookTime":"20 分钟","servings":"10","diabetesNote":"在计划好份量的前提下，较高蛋白的烘焙选择可能比精制面包更容易安排。","carbAwareness":"面包类食物仍需计入碳水；建议搭配蛋白质和蔬菜。","ingredients":["3 杯全脂马苏里拉奶酪丝","约 140 克奶油奶酪","2 杯杏仁粉","1 汤匙泡打粉","1 茶匙蒜粉","3 个鸡蛋","2 茶匙干迷迭香","1 茶匙盐"],"instructions":["烤箱预热至约 220 摄氏度，烤盘铺上烘焙纸。","将马苏里拉奶酪和奶油奶酪微波 90 秒，搅拌；如仍未完全融化，可再次微波。","将杏仁粉、泡打粉和蒜粉搅拌至无结块。","加入鸡蛋和融化奶酪混合物，揉成面团。","把面团压成约 0.6 厘米厚的扁平长方形。","淋上橄榄油，撒上迷迭香和盐。","烘烤 10-12 分钟，期间留意边缘上色。","稍微放凉后切块。需要时可用小烤箱复热。"],"nutrition":["297 千卡","7 克碳水化合物","25 克总脂肪","3 克纤维","15 克蛋白质"]},"zh-TW":{"title":"高蛋白迷迭香佛卡夏","category":"備餐","excerpt":"用馬蘇裏拉奶酪、奶油奶酪、杏仁粉、雞蛋和迷迭香製作的鹹香低碳水面包。","tags":["高蛋白","配菜","備餐"],"prepTime":"10 分鐘","cookTime":"20 分鐘","servings":"10","diabetesNote":"在計劃好份量的前提下，較高蛋白的烘焙選擇可能比精製麪包更容易安排。","carbAwareness":"麪包類食物仍需計入碳水；建議搭配蛋白質和蔬菜。","ingredients":["3 杯全脂馬蘇裏拉奶酪絲","約 140 克奶油奶酪","2 杯杏仁粉","1 湯匙泡打粉","1 茶匙蒜粉","3 個雞蛋","2 茶匙幹迷迭香","1 茶匙鹽"],"instructions":["烤箱預熱至約 220 攝氏度，烤盤鋪上烘焙紙。","將馬蘇裏拉奶酪和奶油奶酪微波 90 秒，攪拌；如仍未完全融化，可再次微波。","將杏仁粉、泡打粉和蒜粉攪拌至無結塊。","加入雞蛋和融化奶酪混合物，揉成麪糰。","把麪糰壓成約 0.6 釐米厚的扁平長方形。","淋上橄欖油，撒上迷迭香和鹽。","烘烤 10-12 分鐘，期間留意邊緣上色。","稍微放涼後切塊。需要時可用小烤箱復熱。"],"nutrition":["297 千卡","7 克碳水化合物","25 克總脂肪","3 克纖維","15 克蛋白質"]},"es":{"title":"Focaccia de romero alta en proteína","category":"Preparación de comidas","excerpt":"Un pan salado bajo en carbohidratos hecho con mozzarella, queso crema, harina de almendra, huevos y romero.","tags":["Alta en proteína","Acompañamiento","Meal prep"],"prepTime":"10 min","cookTime":"20 min","servings":"10","diabetesNote":"Las opciones horneadas con más proteína pueden encajar mejor que el pan refinado cuando se planifican las porciones.","carbAwareness":"Los alimentos tipo pan aún cuentan como carbohidratos; combínelos con proteína y verduras.","ingredients":["3 tazas de queso mozzarella entero rallado","5 oz de queso crema","2 tazas de harina de almendra","1 cucharada de polvo de hornear","1 cucharadita de ajo en polvo","3 huevos","2 cucharaditas de romero seco","1 cucharadita de sal"],"instructions":["Precaliente el horno a 425 F y cubra una bandeja con papel pergamino.","Caliente en microondas la mozzarella y el queso crema por 90 segundos, revuelva y caliente de nuevo si es necesario hasta que se derritan.","Bata la harina de almendra, el polvo de hornear y el ajo en polvo hasta que no queden grumos.","Agregue los huevos y la mezcla de quesos derretidos; procese hasta formar una bola de masa.","Presione la masa hasta formar un rectángulo plano de aproximadamente 1/4 de pulgada de grosor.","Rocíe con aceite de oliva y espolvoree romero y sal.","Hornee de 10 a 12 minutos, revisando con frecuencia, hasta que los bordes se doren.","Deje enfriar brevemente antes de cortar. Recaliente en horno tostador si desea."],"nutrition":["297 calorías","7 g de carbohidratos","25 g de grasa total","3 g de fibra","15 g de proteína"]}}}','{"image":"/recipe-covers/rosemary-focaccia.webp","originalCard":"/recipe-cards/rosemary-focaccia-card.webp","date":"2025-01-06","translations":{"en":{"title":"High-Protein Rosemary Focaccia","category":"Meal prep","excerpt":"A savory low-carb bread made with mozzarella, cream cheese, almond flour, eggs, and rosemary.","tags":["High Protein","Side","Meal Prep"],"prepTime":"10 min","cookTime":"20 min","servings":"10","diabetesNote":"Higher-protein baked options may fit better than refined bread when portions are planned.","carbAwareness":"Bread-style foods still count as carbohydrate; pair with protein and vegetables.","ingredients":["3 cup full-fat shredded mozzarella cheese","5 oz cream cheese","2 cup almond flour","1 tbsp baking powder","1 tsp garlic powder","3 eggs","2 tsp dried rosemary","1 tsp salt"],"instructions":["Preheat oven to 425 F and line a baking sheet with parchment paper.","Microwave mozzarella and cream cheese for 90 seconds, stir, then microwave again if needed until melted.","Whisk almond flour, baking powder, and garlic powder until no lumps appear.","Add eggs and melted cheese mixture; process into a dough ball.","Press dough into a flat rectangle about 1/4 inch thick.","Drizzle with olive oil and sprinkle with rosemary and salt.","Bake 10-12 minutes, checking frequently, until edges brown.","Cool briefly before cutting. Reheat in toaster oven if desired."],"nutrition":["297 calories","7g carbohydrates","25g total fat","3g fiber","15g protein"]},"zh-CN":{"title":"高蛋白迷迭香佛卡夏","category":"备餐","excerpt":"用马苏里拉奶酪、奶油奶酪、杏仁粉、鸡蛋和迷迭香制作的咸香低碳水面包。","tags":["高蛋白","配菜","备餐"],"prepTime":"10 分钟","cookTime":"20 分钟","servings":"10","diabetesNote":"在计划好份量的前提下，较高蛋白的烘焙选择可能比精制面包更容易安排。","carbAwareness":"面包类食物仍需计入碳水；建议搭配蛋白质和蔬菜。","ingredients":["3 杯全脂马苏里拉奶酪丝","约 140 克奶油奶酪","2 杯杏仁粉","1 汤匙泡打粉","1 茶匙蒜粉","3 个鸡蛋","2 茶匙干迷迭香","1 茶匙盐"],"instructions":["烤箱预热至约 220 摄氏度，烤盘铺上烘焙纸。","将马苏里拉奶酪和奶油奶酪微波 90 秒，搅拌；如仍未完全融化，可再次微波。","将杏仁粉、泡打粉和蒜粉搅拌至无结块。","加入鸡蛋和融化奶酪混合物，揉成面团。","把面团压成约 0.6 厘米厚的扁平长方形。","淋上橄榄油，撒上迷迭香和盐。","烘烤 10-12 分钟，期间留意边缘上色。","稍微放凉后切块。需要时可用小烤箱复热。"],"nutrition":["297 千卡","7 克碳水化合物","25 克总脂肪","3 克纤维","15 克蛋白质"]},"zh-TW":{"title":"高蛋白迷迭香佛卡夏","category":"備餐","excerpt":"用馬蘇裏拉奶酪、奶油奶酪、杏仁粉、雞蛋和迷迭香製作的鹹香低碳水面包。","tags":["高蛋白","配菜","備餐"],"prepTime":"10 分鐘","cookTime":"20 分鐘","servings":"10","diabetesNote":"在計劃好份量的前提下，較高蛋白的烘焙選擇可能比精製麪包更容易安排。","carbAwareness":"麪包類食物仍需計入碳水；建議搭配蛋白質和蔬菜。","ingredients":["3 杯全脂馬蘇裏拉奶酪絲","約 140 克奶油奶酪","2 杯杏仁粉","1 湯匙泡打粉","1 茶匙蒜粉","3 個雞蛋","2 茶匙幹迷迭香","1 茶匙鹽"],"instructions":["烤箱預熱至約 220 攝氏度，烤盤鋪上烘焙紙。","將馬蘇裏拉奶酪和奶油奶酪微波 90 秒，攪拌；如仍未完全融化，可再次微波。","將杏仁粉、泡打粉和蒜粉攪拌至無結塊。","加入雞蛋和融化奶酪混合物，揉成麪糰。","把麪糰壓成約 0.6 釐米厚的扁平長方形。","淋上橄欖油，撒上迷迭香和鹽。","烘烤 10-12 分鐘，期間留意邊緣上色。","稍微放涼後切塊。需要時可用小烤箱復熱。"],"nutrition":["297 千卡","7 克碳水化合物","25 克總脂肪","3 克纖維","15 克蛋白質"]},"es":{"title":"Focaccia de romero alta en proteína","category":"Preparación de comidas","excerpt":"Un pan salado bajo en carbohidratos hecho con mozzarella, queso crema, harina de almendra, huevos y romero.","tags":["Alta en proteína","Acompañamiento","Meal prep"],"prepTime":"10 min","cookTime":"20 min","servings":"10","diabetesNote":"Las opciones horneadas con más proteína pueden encajar mejor que el pan refinado cuando se planifican las porciones.","carbAwareness":"Los alimentos tipo pan aún cuentan como carbohidratos; combínelos con proteína y verduras.","ingredients":["3 tazas de queso mozzarella entero rallado","5 oz de queso crema","2 tazas de harina de almendra","1 cucharada de polvo de hornear","1 cucharadita de ajo en polvo","3 huevos","2 cucharaditas de romero seco","1 cucharadita de sal"],"instructions":["Precaliente el horno a 425 F y cubra una bandeja con papel pergamino.","Caliente en microondas la mozzarella y el queso crema por 90 segundos, revuelva y caliente de nuevo si es necesario hasta que se derritan.","Bata la harina de almendra, el polvo de hornear y el ajo en polvo hasta que no queden grumos.","Agregue los huevos y la mezcla de quesos derretidos; procese hasta formar una bola de masa.","Presione la masa hasta formar un rectángulo plano de aproximadamente 1/4 de pulgada de grosor.","Rocíe con aceite de oliva y espolvoree romero y sal.","Hornee de 10 a 12 minutos, revisando con frecuencia, hasta que los bordes se doren.","Deje enfriar brevemente antes de cortar. Recaliente en horno tostador si desea."],"nutrition":["297 calorías","7 g de carbohidratos","25 g de grasa total","3 g de fibra","15 g de proteína"]}}}','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_chicken-salad-collard-wraps','chicken-salad-collard-wraps','{"image":"/recipe-covers/chicken-salad-collard-wraps.webp","originalCard":"/recipe-cards/chicken-salad-collard-wraps-card.webp","date":"2025-01-06","translations":{"en":{"title":"Chicken Salad Collard Wraps","category":"Low-carb lunch","excerpt":"A low-carb wrap with chicken salad, avocado, herbs, walnuts, and collard leaves.","tags":["Lunch","Low Carb","High Protein"],"prepTime":"15 min","cookTime":"5 min","servings":"2","diabetesNote":"Leafy wraps can lower refined carbohydrate load while keeping lunch filling.","carbAwareness":"Add fruit or whole grains on the side if your meal plan calls for more carbohydrates.","ingredients":["4 collard leaves, trimmed","2 cups chicken breast, pre-cooked","1/4 cup unsweetened mayonnaise","2 scallions, chopped","2 tbsp parsley, chopped","1/3 cup raw walnuts, chopped","Salt, to taste","Black pepper, to taste","1/2 avocado, sliced"],"instructions":["Shred cooked chicken into a large bowl.","Remove collard stems, shave thick spines, and blanch briefly in hot water to soften.","Chop scallions, parsley, and walnuts; slice avocado.","Mix chicken with mayonnaise, scallions, parsley, walnuts, salt, and pepper.","Place collard leaf stem-side up, add chicken mixture and avocado, then roll into a wrap.","Repeat with remaining collard leaves."],"nutrition":["638 calories","9g carbohydrates","52g total fat","5g fiber","40g protein"]},"zh-CN":{"title":"鸡肉沙拉羽衣甘蓝卷","category":"低碳水午餐","excerpt":"低碳水卷饼做法，使用鸡肉沙拉、牛油果、香草、核桃和羽衣甘蓝叶。","tags":["午餐","低碳水","高蛋白"],"prepTime":"15 分钟","cookTime":"5 分钟","servings":"2","diabetesNote":"用叶菜做卷皮可降低精制碳水负荷，同时让午餐更有饱足感。","carbAwareness":"如果您的餐食计划需要更多碳水，可在旁边搭配水果或全谷物。","ingredients":["4 片羽衣甘蓝叶，修整好","2 杯熟鸡胸肉","1/4 杯无糖蛋黄酱","2 根青葱，切碎","2 汤匙欧芹，切碎","1/3 杯生核桃，切碎","盐，适量","黑胡椒，适量","1/2 个牛油果，切片"],"instructions":["将熟鸡肉撕碎，放入大碗。","去除羽衣甘蓝叶的粗梗，削薄较厚叶脉，并在热水中快速焯烫使其变软。","切碎青葱、欧芹和核桃；牛油果切片。","将鸡肉与蛋黄酱、青葱、欧芹、核桃、盐和黑胡椒拌匀。","把羽衣甘蓝叶梗面朝上，放入鸡肉混合物和牛油果，然后卷起。","用剩余叶片重复操作。"],"nutrition":["638 千卡","9 克碳水化合物","52 克总脂肪","5 克纤维","40 克蛋白质"]},"zh-TW":{"title":"雞肉沙拉羽衣甘藍卷","category":"低碳水午餐","excerpt":"低碳水捲餅做法，使用雞肉沙拉、牛油果、香草、核桃和羽衣甘藍葉。","tags":["午餐","低碳水","高蛋白"],"prepTime":"15 分鐘","cookTime":"5 分鐘","servings":"2","diabetesNote":"用葉菜做卷皮可降低精製碳水負荷，同時讓午餐更有飽足感。","carbAwareness":"如果您的餐食計劃需要更多碳水，可在旁邊搭配水果或全穀物。","ingredients":["4 片羽衣甘藍葉，修整好","2 杯熟雞胸肉","1/4 杯無糖蛋黃醬","2 根青蔥，切碎","2 湯匙歐芹，切碎","1/3 杯生核桃，切碎","鹽，適量","黑胡椒，適量","1/2 個牛油果，切片"],"instructions":["將熟雞肉撕碎，放入大碗。","去除羽衣甘藍葉的粗梗，削薄較厚葉脈，並在熱水中快速焯燙使其變軟。","切碎青蔥、歐芹和核桃；牛油果切片。","將雞肉與蛋黃醬、青蔥、歐芹、核桃、鹽和黑胡椒拌勻。","把羽衣甘藍葉梗面朝上，放入雞肉混合物和牛油果，然後捲起。","用剩餘葉片重複操作。"],"nutrition":["638 千卡","9 克碳水化合物","52 克總脂肪","5 克纖維","40 克蛋白質"]},"es":{"title":"Wraps de ensalada de pollo con hojas de collard","category":"Almuerzo bajo en carbohidratos","excerpt":"Un wrap bajo en carbohidratos con ensalada de pollo, aguacate, hierbas, nueces y hojas de collard.","tags":["Almuerzo","Baja en carbohidratos","Alta en proteína"],"prepTime":"15 min","cookTime":"5 min","servings":"2","diabetesNote":"Los wraps de hojas verdes pueden reducir la carga de carbohidratos refinados y mantener el almuerzo saciante.","carbAwareness":"Agregue fruta o granos integrales al lado si su plan de comidas requiere más carbohidratos.","ingredients":["4 hojas de collard, recortadas","2 tazas de pechuga de pollo precocida","1/4 taza de mayonesa sin azúcar","2 cebollines, picados","2 cucharadas de perejil, picado","1/3 taza de nueces crudas, picadas","Sal, al gusto","Pimienta negra, al gusto","1/2 aguacate, en rebanadas"],"instructions":["Desmenuce el pollo cocido en un tazón grande.","Retire los tallos de las hojas de collard, rebaje las nervaduras gruesas y escáldelas brevemente en agua caliente para ablandarlas.","Pique los cebollines, el perejil y las nueces; corte el aguacate.","Mezcle el pollo con la mayonesa, los cebollines, el perejil, las nueces, la sal y la pimienta.","Coloque una hoja de collard con el lado del tallo hacia arriba, agregue la mezcla de pollo y aguacate, y enrolle como wrap.","Repita con las hojas restantes."],"nutrition":["638 calorías","9 g de carbohidratos","52 g de grasa total","5 g de fibra","40 g de proteína"]}}}','{"image":"/recipe-covers/chicken-salad-collard-wraps.webp","originalCard":"/recipe-cards/chicken-salad-collard-wraps-card.webp","date":"2025-01-06","translations":{"en":{"title":"Chicken Salad Collard Wraps","category":"Low-carb lunch","excerpt":"A low-carb wrap with chicken salad, avocado, herbs, walnuts, and collard leaves.","tags":["Lunch","Low Carb","High Protein"],"prepTime":"15 min","cookTime":"5 min","servings":"2","diabetesNote":"Leafy wraps can lower refined carbohydrate load while keeping lunch filling.","carbAwareness":"Add fruit or whole grains on the side if your meal plan calls for more carbohydrates.","ingredients":["4 collard leaves, trimmed","2 cups chicken breast, pre-cooked","1/4 cup unsweetened mayonnaise","2 scallions, chopped","2 tbsp parsley, chopped","1/3 cup raw walnuts, chopped","Salt, to taste","Black pepper, to taste","1/2 avocado, sliced"],"instructions":["Shred cooked chicken into a large bowl.","Remove collard stems, shave thick spines, and blanch briefly in hot water to soften.","Chop scallions, parsley, and walnuts; slice avocado.","Mix chicken with mayonnaise, scallions, parsley, walnuts, salt, and pepper.","Place collard leaf stem-side up, add chicken mixture and avocado, then roll into a wrap.","Repeat with remaining collard leaves."],"nutrition":["638 calories","9g carbohydrates","52g total fat","5g fiber","40g protein"]},"zh-CN":{"title":"鸡肉沙拉羽衣甘蓝卷","category":"低碳水午餐","excerpt":"低碳水卷饼做法，使用鸡肉沙拉、牛油果、香草、核桃和羽衣甘蓝叶。","tags":["午餐","低碳水","高蛋白"],"prepTime":"15 分钟","cookTime":"5 分钟","servings":"2","diabetesNote":"用叶菜做卷皮可降低精制碳水负荷，同时让午餐更有饱足感。","carbAwareness":"如果您的餐食计划需要更多碳水，可在旁边搭配水果或全谷物。","ingredients":["4 片羽衣甘蓝叶，修整好","2 杯熟鸡胸肉","1/4 杯无糖蛋黄酱","2 根青葱，切碎","2 汤匙欧芹，切碎","1/3 杯生核桃，切碎","盐，适量","黑胡椒，适量","1/2 个牛油果，切片"],"instructions":["将熟鸡肉撕碎，放入大碗。","去除羽衣甘蓝叶的粗梗，削薄较厚叶脉，并在热水中快速焯烫使其变软。","切碎青葱、欧芹和核桃；牛油果切片。","将鸡肉与蛋黄酱、青葱、欧芹、核桃、盐和黑胡椒拌匀。","把羽衣甘蓝叶梗面朝上，放入鸡肉混合物和牛油果，然后卷起。","用剩余叶片重复操作。"],"nutrition":["638 千卡","9 克碳水化合物","52 克总脂肪","5 克纤维","40 克蛋白质"]},"zh-TW":{"title":"雞肉沙拉羽衣甘藍卷","category":"低碳水午餐","excerpt":"低碳水捲餅做法，使用雞肉沙拉、牛油果、香草、核桃和羽衣甘藍葉。","tags":["午餐","低碳水","高蛋白"],"prepTime":"15 分鐘","cookTime":"5 分鐘","servings":"2","diabetesNote":"用葉菜做卷皮可降低精製碳水負荷，同時讓午餐更有飽足感。","carbAwareness":"如果您的餐食計劃需要更多碳水，可在旁邊搭配水果或全穀物。","ingredients":["4 片羽衣甘藍葉，修整好","2 杯熟雞胸肉","1/4 杯無糖蛋黃醬","2 根青蔥，切碎","2 湯匙歐芹，切碎","1/3 杯生核桃，切碎","鹽，適量","黑胡椒，適量","1/2 個牛油果，切片"],"instructions":["將熟雞肉撕碎，放入大碗。","去除羽衣甘藍葉的粗梗，削薄較厚葉脈，並在熱水中快速焯燙使其變軟。","切碎青蔥、歐芹和核桃；牛油果切片。","將雞肉與蛋黃醬、青蔥、歐芹、核桃、鹽和黑胡椒拌勻。","把羽衣甘藍葉梗面朝上，放入雞肉混合物和牛油果，然後捲起。","用剩餘葉片重複操作。"],"nutrition":["638 千卡","9 克碳水化合物","52 克總脂肪","5 克纖維","40 克蛋白質"]},"es":{"title":"Wraps de ensalada de pollo con hojas de collard","category":"Almuerzo bajo en carbohidratos","excerpt":"Un wrap bajo en carbohidratos con ensalada de pollo, aguacate, hierbas, nueces y hojas de collard.","tags":["Almuerzo","Baja en carbohidratos","Alta en proteína"],"prepTime":"15 min","cookTime":"5 min","servings":"2","diabetesNote":"Los wraps de hojas verdes pueden reducir la carga de carbohidratos refinados y mantener el almuerzo saciante.","carbAwareness":"Agregue fruta o granos integrales al lado si su plan de comidas requiere más carbohidratos.","ingredients":["4 hojas de collard, recortadas","2 tazas de pechuga de pollo precocida","1/4 taza de mayonesa sin azúcar","2 cebollines, picados","2 cucharadas de perejil, picado","1/3 taza de nueces crudas, picadas","Sal, al gusto","Pimienta negra, al gusto","1/2 aguacate, en rebanadas"],"instructions":["Desmenuce el pollo cocido en un tazón grande.","Retire los tallos de las hojas de collard, rebaje las nervaduras gruesas y escáldelas brevemente en agua caliente para ablandarlas.","Pique los cebollines, el perejil y las nueces; corte el aguacate.","Mezcle el pollo con la mayonesa, los cebollines, el perejil, las nueces, la sal y la pimienta.","Coloque una hoja de collard con el lado del tallo hacia arriba, agregue la mezcla de pollo y aguacate, y enrolle como wrap.","Repita con las hojas restantes."],"nutrition":["638 calorías","9 g de carbohidratos","52 g de grasa total","5 g de fibra","40 g de proteína"]}}}','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_chicken-sausage-kale-skillet','chicken-sausage-kale-skillet','{"image":"/recipe-covers/chicken-sausage-kale-skillet.webp","originalCard":"/recipe-cards/chicken-sausage-kale-skillet-card.webp","date":"2025-01-06","translations":{"en":{"title":"Chicken Sausage Kale Skillet","category":"Quick skillet","excerpt":"A nutrient-dense skillet with chicken sausage and kale.","tags":["Dinner","Quick Meals","High Protein"],"prepTime":"10 min","cookTime":"5 min","servings":"2","diabetesNote":"A protein-and-vegetable base can anchor a balanced plate.","carbAwareness":"Check sausage labels for added sugars and sodium.","ingredients":["12 oz uncured, unsweetened gluten-free sausage","8 oz kale, spines removed and chopped"],"instructions":["Remove spines from kale and chop leaves.","Slice sausage and preheat a heavy skillet.","Brown sausage on all sides.","Stir in kale, remove from heat, and cover to allow kale to wilt."],"nutrition":["599 calories","7g carbohydrates","53g total fat","5g fiber","23g protein"]},"zh-CN":{"title":"鸡肉香肠羽衣甘蓝煎锅菜","category":"快速煎锅餐","excerpt":"用鸡肉香肠和羽衣甘蓝制作的营养密度高的煎锅餐。","tags":["晚餐","快手餐","高蛋白"],"prepTime":"10 分钟","cookTime":"5 分钟","servings":"2","diabetesNote":"以蛋白质和蔬菜为基础，有助于建立更均衡的餐盘。","carbAwareness":"查看香肠标签，留意添加糖和钠含量。","ingredients":["约 340 克未腌制、无糖、无麸质香肠","约 225 克羽衣甘蓝，去除粗梗并切碎"],"instructions":["去除羽衣甘蓝粗梗，并切碎叶片。","香肠切片，预热厚底煎锅。","将香肠各面煎至上色。","拌入羽衣甘蓝，离火并盖上锅盖，让羽衣甘蓝利用余热变软。"],"nutrition":["599 千卡","7 克碳水化合物","53 克总脂肪","5 克纤维","23 克蛋白质"]},"zh-TW":{"title":"雞肉香腸羽衣甘藍煎鍋菜","category":"快速煎鍋餐","excerpt":"用雞肉香腸和羽衣甘藍製作的營養密度高的煎鍋餐。","tags":["晚餐","快手餐","高蛋白"],"prepTime":"10 分鐘","cookTime":"5 分鐘","servings":"2","diabetesNote":"以蛋白質和蔬菜爲基礎，有助於建立更均衡的餐盤。","carbAwareness":"查看香腸標籤，留意添加糖和鈉含量。","ingredients":["約 340 克未醃製、無糖、無麩質香腸","約 225 克羽衣甘藍，去除粗梗並切碎"],"instructions":["去除羽衣甘藍粗梗，並切碎葉片。","香腸切片，預熱厚底煎鍋。","將香腸各面煎至上色。","拌入羽衣甘藍，離火併蓋上鍋蓋，讓羽衣甘藍利用餘熱變軟。"],"nutrition":["599 千卡","7 克碳水化合物","53 克總脂肪","5 克纖維","23 克蛋白質"]},"es":{"title":"Sartén de salchicha de pollo y kale","category":"Sartén rápida","excerpt":"Una preparación en sartén rica en nutrientes con salchicha de pollo y kale.","tags":["Cena","Comidas rápidas","Alta en proteína"],"prepTime":"10 min","cookTime":"5 min","servings":"2","diabetesNote":"Una base de proteína y verduras puede sostener un plato equilibrado.","carbAwareness":"Revise las etiquetas de la salchicha para detectar azúcares añadidos y sodio.","ingredients":["12 oz de salchicha sin curar, sin azúcar y sin gluten","8 oz de kale, sin nervaduras y picado"],"instructions":["Retire las nervaduras del kale y pique las hojas.","Corte la salchicha en rebanadas y precaliente una sartén pesada.","Dore la salchicha por todos los lados.","Agregue el kale, retire del fuego y cubra para que el kale se marchite."],"nutrition":["599 calorías","7 g de carbohidratos","53 g de grasa total","5 g de fibra","23 g de proteína"]}}}','{"image":"/recipe-covers/chicken-sausage-kale-skillet.webp","originalCard":"/recipe-cards/chicken-sausage-kale-skillet-card.webp","date":"2025-01-06","translations":{"en":{"title":"Chicken Sausage Kale Skillet","category":"Quick skillet","excerpt":"A nutrient-dense skillet with chicken sausage and kale.","tags":["Dinner","Quick Meals","High Protein"],"prepTime":"10 min","cookTime":"5 min","servings":"2","diabetesNote":"A protein-and-vegetable base can anchor a balanced plate.","carbAwareness":"Check sausage labels for added sugars and sodium.","ingredients":["12 oz uncured, unsweetened gluten-free sausage","8 oz kale, spines removed and chopped"],"instructions":["Remove spines from kale and chop leaves.","Slice sausage and preheat a heavy skillet.","Brown sausage on all sides.","Stir in kale, remove from heat, and cover to allow kale to wilt."],"nutrition":["599 calories","7g carbohydrates","53g total fat","5g fiber","23g protein"]},"zh-CN":{"title":"鸡肉香肠羽衣甘蓝煎锅菜","category":"快速煎锅餐","excerpt":"用鸡肉香肠和羽衣甘蓝制作的