INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_dijon-salmon-spinach','dijon-salmon-spinach','{"image":"/recipe-covers/dijon-salmon-spinach.webp","originalCard":"/recipe-cards/dijon-salmon-spinach-card.webp","date":"2025-01-06","translations":{"en":{"title":"Dijon Salmon with Spinach","category":"Heart-healthy dinner","excerpt":"Baked Dijon salmon served over spinach with lemon and herbs.","tags":["Heart Healthy","Dinner","Protein"],"prepTime":"15 min","cookTime":"15 min","servings":"4","diabetesNote":"Omega-3-rich fish and non-starchy vegetables make this a strong glucose-aware dinner.","carbAwareness":"Pair with a measured portion of beans, lentils, quinoa, or brown rice if you need more energy.","ingredients":["1 1/2 lb salmon, cut into filets","2 tbsp Dijon mustard","2 cloves garlic, crushed","1 1/2 tbsp olive oil","1/2 lemon, juiced","1 tbsp maple syrup","1/4 cup scallions, chopped","Parchment paper","6 cup spinach","1 lemon, juiced","2 tbsp olive oil"],"instructions":["De-bone salmon filets and preheat oven to 400 F.","Crush garlic, juice lemon, chop scallions, and line a baking sheet with parchment.","Arrange filets on baking sheet.","Mix mustard, garlic, oil, lemon juice, and maple syrup.","Spoon mixture over filets and bake 12-15 minutes until cooked through.","Toss spinach with lemon juice, olive oil, and salt.","Serve salmon over spinach."],"nutrition":["388 calories","8g carbohydrates","23g total fat","0g fiber","35g protein"]},"zh-CN":{"title":"Dijon 三文鱼配菠菜","category":"护心晚餐","excerpt":"烤 Dijon 三文鱼，搭配柠檬香草菠菜。","tags":["护心","晚餐","蛋白质"],"prepTime":"15 分钟","cookTime":"15 分钟","servings":"4","diabetesNote":"富含 Omega-3 的鱼类和非淀粉类蔬菜，是兼顾血糖意识的优质晚餐组合。","carbAwareness":"如果需要更多能量，可搭配定量豆类、扁豆、藜麦或糙米。","ingredients":["约 680 克三文鱼，切成鱼排","2 汤匙第戎芥末酱","2 瓣大蒜，压碎","1 1/2 汤匙橄榄油","1/2 个柠檬，榨汁","1 汤匙枫糖浆","1/4 杯青葱，切碎","烘焙纸","6 杯菠菜","1 个柠檬，榨汁","2 汤匙橄榄油"],"instructions":["去除三文鱼鱼刺，并将烤箱预热至约 200 摄氏度。","压碎大蒜，榨柠檬汁，切碎青葱，并在烤盘上铺烘焙纸。","将鱼排放在烤盘上。","混合芥末酱、大蒜、油、柠檬汁和枫糖浆。","把混合酱汁舀在鱼排上，烤 12-15 分钟至熟透。","将菠菜与柠檬汁、橄榄油和盐拌匀。","把三文鱼放在菠菜上食用。"],"nutrition":["388 千卡","8 克碳水化合物","23 克总脂肪","0 克纤维","35 克蛋白质"]},"zh-TW":{"title":"Dijon 三文魚配菠菜","category":"護心晚餐","excerpt":"烤 Dijon 三文魚，搭配檸檬香草菠菜。","tags":["護心","晚餐","蛋白質"],"prepTime":"15 分鐘","cookTime":"15 分鐘","servings":"4","diabetesNote":"富含 Omega-3 的魚類和非澱粉類蔬菜，是兼顧血糖意識的優質晚餐組合。","carbAwareness":"如果需要更多能量，可搭配定量豆類、扁豆、藜麥或糙米。","ingredients":["約 680 克三文魚，切成魚排","2 湯匙第戎芥末醬","2 瓣大蒜，壓碎","1 1/2 湯匙橄欖油","1/2 個檸檬，榨汁","1 湯匙楓糖漿","1/4 杯青蔥，切碎","烘焙紙","6 杯菠菜","1 個檸檬，榨汁","2 湯匙橄欖油"],"instructions":["去除三文魚魚刺，並將烤箱預熱至約 200 攝氏度。","壓碎大蒜，榨檸檬汁，切碎青蔥，並在烤盤上鋪烘焙紙。","將魚排放在烤盤上。","混合芥末醬、大蒜、油、檸檬汁和楓糖漿。","把混合醬汁舀在魚排上，烤 12-15 分鐘至熟透。","將菠菜與檸檬汁、橄欖油和鹽拌勻。","把三文魚放在菠菜上食用。"],"nutrition":["388 千卡","8 克碳水化合物","23 克總脂肪","0 克纖維","35 克蛋白質"]},"es":{"title":"Salmón Dijon con espinaca","category":"Cena saludable para el corazón","excerpt":"Salmón al horno con Dijon servido sobre espinaca con limón y hierbas.","tags":["Salud del corazón","Cena","Proteína"],"prepTime":"15 min","cookTime":"15 min","servings":"4","diabetesNote":"El pescado rico en omega-3 y las verduras sin almidón hacen de esta una cena sólida para cuidar la glucosa.","carbAwareness":"Acompañe con una porción medida de frijoles, lentejas, quinoa o arroz integral si necesita más energía.","ingredients":["1 1/2 lb de salmón, cortado en filetes","2 cucharadas de mostaza Dijon","2 dientes de ajo, machacados","1 1/2 cucharadas de aceite de oliva","Jugo de 1/2 limón","1 cucharada de jarabe de maple","1/4 taza de cebollines, picados","Papel pergamino","6 tazas de espinaca","Jugo de 1 limón","2 cucharadas de aceite de oliva"],"instructions":["Retire las espinas de los filetes de salmón y precaliente el horno a 400 F.","Machaque el ajo, exprima el limón, pique los cebollines y cubra una bandeja con papel pergamino.","Acomode los filetes en la bandeja.","Mezcle la mostaza, el ajo, el aceite, el jugo de limón y el jarabe de maple.","Coloque la mezcla sobre los filetes y hornee de 12 a 15 minutos, hasta que estén cocidos.","Mezcle la espinaca con jugo de limón, aceite de oliva y sal.","Sirva el salmón sobre la espinaca."],"nutrition":["388 calorías","8 g de carbohidratos","23 g de grasa total","0 g de fibra","35 g de proteína"]}}}','{"image":"/recipe-covers/dijon-salmon-spinach.webp","originalCard":"/recipe-cards/dijon-salmon-spinach-card.webp","date":"2025-01-06","translations":{"en":{"title":"Dijon Salmon with Spinach","category":"Heart-healthy dinner","excerpt":"Baked Dijon salmon served over spinach with lemon and herbs.","tags":["Heart Healthy","Dinner","Protein"],"prepTime":"15 min","cookTime":"15 min","servings":"4","diabetesNote":"Omega-3-rich fish and non-starchy vegetables make this a strong glucose-aware dinner.","carbAwareness":"Pair with a measured portion of beans, lentils, quinoa, or brown rice if you need more energy.","ingredients":["1 1/2 lb salmon, cut into filets","2 tbsp Dijon mustard","2 cloves garlic, crushed","1 1/2 tbsp olive oil","1/2 lemon, juiced","1 tbsp maple syrup","1/4 cup scallions, chopped","Parchment paper","6 cup spinach","1 lemon, juiced","2 tbsp olive oil"],"instructions":["De-bone salmon filets and preheat oven to 400 F.","Crush garlic, juice lemon, chop scallions, and line a baking sheet with parchment.","Arrange filets on baking sheet.","Mix mustard, garlic, oil, lemon juice, and maple syrup.","Spoon mixture over filets and bake 12-15 minutes until cooked through.","Toss spinach with lemon juice, olive oil, and salt.","Serve salmon over spinach."],"nutrition":["388 calories","8g carbohydrates","23g total fat","0g fiber","35g protein"]},"zh-CN":{"title":"Dijon 三文鱼配菠菜","category":"护心晚餐","excerpt":"烤 Dijon 三文鱼，搭配柠檬香草菠菜。","tags":["护心","晚餐","蛋白质"],"prepTime":"15 分钟","cookTime":"15 分钟","servings":"4","diabetesNote":"富含 Omega-3 的鱼类和非淀粉类蔬菜，是兼顾血糖意识的优质晚餐组合。","carbAwareness":"如果需要更多能量，可搭配定量豆类、扁豆、藜麦或糙米。","ingredients":["约 680 克三文鱼，切成鱼排","2 汤匙第戎芥末酱","2 瓣大蒜，压碎","1 1/2 汤匙橄榄油","1/2 个柠檬，榨汁","1 汤匙枫糖浆","1/4 杯青葱，切碎","烘焙纸","6 杯菠菜","1 个柠檬，榨汁","2 汤匙橄榄油"],"instructions":["去除三文鱼鱼刺，并将烤箱预热至约 200 摄氏度。","压碎大蒜，榨柠檬汁，切碎青葱，并在烤盘上铺烘焙纸。","将鱼排放在烤盘上。","混合芥末酱、大蒜、油、柠檬汁和枫糖浆。","把混合酱汁舀在鱼排上，烤 12-15 分钟至熟透。","将菠菜与柠檬汁、橄榄油和盐拌匀。","把三文鱼放在菠菜上食用。"],"nutrition":["388 千卡","8 克碳水化合物","23 克总脂肪","0 克纤维","35 克蛋白质"]},"zh-TW":{"title":"Dijon 三文魚配菠菜","category":"護心晚餐","excerpt":"烤 Dijon 三文魚，搭配檸檬香草菠菜。","tags":["護心","晚餐","蛋白質"],"prepTime":"15 分鐘","cookTime":"15 分鐘","servings":"4","diabetesNote":"富含 Omega-3 的魚類和非澱粉類蔬菜，是兼顧血糖意識的優質晚餐組合。","carbAwareness":"如果需要更多能量，可搭配定量豆類、扁豆、藜麥或糙米。","ingredients":["約 680 克三文魚，切成魚排","2 湯匙第戎芥末醬","2 瓣大蒜，壓碎","1 1/2 湯匙橄欖油","1/2 個檸檬，榨汁","1 湯匙楓糖漿","1/4 杯青蔥，切碎","烘焙紙","6 杯菠菜","1 個檸檬，榨汁","2 湯匙橄欖油"],"instructions":["去除三文魚魚刺，並將烤箱預熱至約 200 攝氏度。","壓碎大蒜，榨檸檬汁，切碎青蔥，並在烤盤上鋪烘焙紙。","將魚排放在烤盤上。","混合芥末醬、大蒜、油、檸檬汁和楓糖漿。","把混合醬汁舀在魚排上，烤 12-15 分鐘至熟透。","將菠菜與檸檬汁、橄欖油和鹽拌勻。","把三文魚放在菠菜上食用。"],"nutrition":["388 千卡","8 克碳水化合物","23 克總脂肪","0 克纖維","35 克蛋白質"]},"es":{"title":"Salmón Dijon con espinaca","category":"Cena saludable para el corazón","excerpt":"Salmón al horno con Dijon servido sobre espinaca con limón y hierbas.","tags":["Salud del corazón","Cena","Proteína"],"prepTime":"15 min","cookTime":"15 min","servings":"4","diabetesNote":"El pescado rico en omega-3 y las verduras sin almidón hacen de esta una cena sólida para cuidar la glucosa.","carbAwareness":"Acompañe con una porción medida de frijoles, lentejas, quinoa o arroz integral si necesita más energía.","ingredients":["1 1/2 lb de salmón, cortado en filetes","2 cucharadas de mostaza Dijon","2 dientes de ajo, machacados","1 1/2 cucharadas de aceite de oliva","Jugo de 1/2 limón","1 cucharada de jarabe de maple","1/4 taza de cebollines, picados","Papel pergamino","6 tazas de espinaca","Jugo de 1 limón","2 cucharadas de aceite de oliva"],"instructions":["Retire las espinas de los filetes de salmón y precaliente el horno a 400 F.","Machaque el ajo, exprima el limón, pique los cebollines y cubra una bandeja con papel pergamino.","Acomode los filetes en la bandeja.","Mezcle la mostaza, el ajo, el aceite, el jugo de limón y el jarabe de maple.","Coloque la mezcla sobre los filetes y hornee de 12 a 15 minutos, hasta que estén cocidos.","Mezcle la espinaca con jugo de limón, aceite de oliva y sal.","Sirva el salmón sobre la espinaca."],"nutrition":["388 calorías","8 g de carbohidratos","23 g de grasa total","0 g de fibra","35 g de proteína"]}}}','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_low-carb-easy-tiramisu','low-carb-easy-tiramisu','{"image":"/recipe-covers/low-carb-tiramisu.webp","originalCard":"/recipe-cards/low-carb-tiramisu-card.webp","date":"2025-01-30","translations":{"en":{"title":"Low-Carb Easy Tiramisu","category":"Dessert","excerpt":"A lighter tiramisu-style dessert with almond crumble, Greek yogurt, mascarpone, coffee, and cocoa.","tags":["Dessert","Low Carb","Treat"],"prepTime":"15 min","cookTime":"3 min","servings":"6","diabetesNote":"Lower-carb desserts can still affect glucose; portion and timing matter.","carbAwareness":"Enjoy as part of a planned meal rather than alone on an empty stomach.","ingredients":["1/2 cup almond flour","1/4 cup plus 1 1/2 tbsp erythritol or other sugar substitute, divided","1 tsp ground cinnamon","1/4 tsp salt","1 tbsp espresso or strong coffee","2 cup plain nonfat Greek yogurt","3 tbsp mascarpone cheese","1 tbsp dark rum","2 tsp orange zest","1 tsp vanilla extract","1 tsp cocoa powder"],"instructions":["Toast almond flour in a skillet over medium heat for 3 minutes or until golden.","Mix toasted almond flour with 1 1/2 tbsp erythritol, cinnamon, salt, and espresso.","Divide almond mixture among 6 serving glasses.","Mix yogurt, mascarpone, remaining erythritol, rum, orange zest, and vanilla.","Spoon cream mixture over almond base and dust with cocoa before serving."],"nutrition":["140 calories","14g carbohydrates","8g total fat","1g fiber","10g protein"]},"zh-CN":{"title":"简易低碳水提拉米苏","category":"甜点","excerpt":"较轻盈的提拉米苏风味甜点，含杏仁碎、希腊酸奶、马斯卡彭奶酪、咖啡和可可。","tags":["甜点","低碳水","享受型小点"],"prepTime":"15 分钟","cookTime":"3 分钟","servings":"6","diabetesNote":"低碳水甜点仍可能影响血糖；份量和食用时机都很重要。","carbAwareness":"建议作为计划餐食的一部分享用，而不是空腹单独食用。","ingredients":["1/2 杯杏仁粉","1/4 杯另加 1 1/2 汤匙赤藓糖醇或其他代糖，分开使用","1 茶匙肉桂粉","1/4 茶匙盐","1 汤匙浓缩咖啡或浓咖啡","2 杯原味脱脂希腊酸奶","3 汤匙马斯卡彭奶酪","1 汤匙黑朗姆酒","2 茶匙橙皮屑","1 茶匙香草精","1 茶匙可可粉"],"instructions":["将杏仁粉放入煎锅，中火翻炒约 3 分钟，直到金黄。","把炒香的杏仁粉与 1 1/2 汤匙赤藓糖醇、肉桂粉、盐和浓缩咖啡混合。","将杏仁混合物分装到 6 个食用杯中。","混合酸奶、马斯卡彭奶酪、剩余赤藓糖醇、朗姆酒、橙皮屑和香草精。","把奶油混合物舀在杏仁底上，食用前撒上可可粉。"],"nutrition":["140 千卡","14 克碳水化合物","8 克总脂肪","1 克纤维","10 克蛋白质"]},"zh-TW":{"title":"簡易低碳水提拉米蘇","category":"甜點","excerpt":"較輕盈的提拉米蘇風味甜點，含杏仁碎、希臘酸奶、馬斯卡彭奶酪、咖啡和可可。","tags":["甜點","低碳水","享受型小點"],"prepTime":"15 分鐘","cookTime":"3 分鐘","servings":"6","diabetesNote":"低碳水甜點仍可能影響血糖；份量和食用時機都很重要。","carbAwareness":"建議作爲計劃餐食的一部分享用，而不是空腹單獨食用。","ingredients":["1/2 杯杏仁粉","1/4 杯另加 1 1/2 湯匙赤蘚糖醇或其他代糖，分開使用","1 茶匙肉桂粉","1/4 茶匙鹽","1 湯匙濃縮咖啡或濃咖啡","2 杯原味脫脂希臘酸奶","3 湯匙馬斯卡彭奶酪","1 湯匙黑朗姆酒","2 茶匙橙皮屑","1 茶匙香草精","1 茶匙可可粉"],"instructions":["將杏仁粉放入煎鍋，中火翻炒約 3 分鐘，直到金黃。","把炒香的杏仁粉與 1 1/2 湯匙赤蘚糖醇、肉桂粉、鹽和濃縮咖啡混合。","將杏仁混合物分裝到 6 個食用杯中。","混合酸奶、馬斯卡彭奶酪、剩餘赤蘚糖醇、朗姆酒、橙皮屑和香草精。","把奶油混合物舀在杏仁底上，食用前撒上可可粉。"],"nutrition":["140 千卡","14 克碳水化合物","8 克總脂肪","1 克纖維","10 克蛋白質"]},"es":{"title":"Tiramisú fácil bajo en carbohidratos","category":"Postre","excerpt":"Un postre ligero estilo tiramisú con crumble de almendra, yogur griego, mascarpone, café y cacao.","tags":["Postre","Bajo en carbohidratos","Antojo"],"prepTime":"15 min","cookTime":"3 min","servings":"6","diabetesNote":"Los postres con menos carbohidratos aún pueden afectar la glucosa; la porción y el momento importan.","carbAwareness":"Disfrútelo como parte de una comida planificada, no solo con el estómago vacío.","ingredients":["1/2 taza de harina de almendra","1/4 taza más 1 1/2 cucharadas de eritritol u otro sustituto de azúcar, dividido","1 cucharadita de canela molida","1/4 cucharadita de sal","1 cucharada de espresso o café fuerte","2 tazas de yogur griego natural sin grasa","3 cucharadas de queso mascarpone","1 cucharada de ron oscuro","2 cucharaditas de ralladura de naranja","1 cucharadita de extracto de vainilla","1 cucharadita de cacao en polvo"],"instructions":["Tueste la harina de almendra en una sartén a fuego medio durante 3 minutos o hasta que esté dorada.","Mezcle la harina de almendra tostada con 1 1/2 cucharadas de eritritol, canela, sal y espresso.","Divida la mezcla de almendra entre 6 vasos para servir.","Mezcle el yogur, el mascarpone, el eritritol restante, el ron, la ralladura de naranja y la vainilla.","Coloque la crema sobre la base de almendra y espolvoree cacao antes de servir."],"nutrition":["140 calorías","14 g de carbohidratos","8 g de grasa total","1 g de fibra","10 g de proteína"]}}}','{"image":"/recipe-covers/low-carb-tiramisu.webp","originalCard":"/recipe-cards/low-carb-tiramisu-card.webp","date":"2025-01-30","translations":{"en":{"title":"Low-Carb Easy Tiramisu","category":"Dessert","excerpt":"A lighter tiramisu-style dessert with almond crumble, Greek yogurt, mascarpone, coffee, and cocoa.","tags":["Dessert","Low Carb","Treat"],"prepTime":"15 min","cookTime":"3 min","servings":"6","diabetesNote":"Lower-carb desserts can still affect glucose; portion and timing matter.","carbAwareness":"Enjoy as part of a planned meal rather than alone on an empty stomach.","ingredients":["1/2 cup almond flour","1/4 cup plus 1 1/2 tbsp erythritol or other sugar substitute, divided","1 tsp ground cinnamon","1/4 tsp salt","1 tbsp espresso or strong coffee","2 cup plain nonfat Greek yogurt","3 tbsp mascarpone cheese","1 tbsp dark rum","2 tsp orange zest","1 tsp vanilla extract","1 tsp cocoa powder"],"instructions":["Toast almond flour in a skillet over medium heat for 3 minutes or until golden.","Mix toasted almond flour with 1 1/2 tbsp erythritol, cinnamon, salt, and espresso.","Divide almond mixture among 6 serving glasses.","Mix yogurt, mascarpone, remaining erythritol, rum, orange zest, and vanilla.","Spoon cream mixture over almond base and dust with cocoa before serving."],"nutrition":["140 calories","14g carbohydrates","8g total fat","1g fiber","10g protein"]},"zh-CN":{"title":"简易低碳水提拉米苏","category":"甜点","excerpt":"较轻盈的提拉米苏风味甜点，含杏仁碎、希腊酸奶、马斯卡彭奶酪、咖啡和可可。","tags":["甜点","低碳水","享受型小点"],"prepTime":"15 分钟","cookTime":"3 分钟","servings":"6","diabetesNote":"低碳水甜点仍可能影响血糖；份量和食用时机都很重要。","carbAwareness":"建议作为计划餐食的一部分享用，而不是空腹单独食用。","ingredients":["1/2 杯杏仁粉","1/4 杯另加 1 1/2 汤匙赤藓糖醇或其他代糖，分开使用","1 茶匙肉桂粉","1/4 茶匙盐","1 汤匙浓缩咖啡或浓咖啡","2 杯原味脱脂希腊酸奶","3 汤匙马斯卡彭奶酪","1 汤匙黑朗姆酒","2 茶匙橙皮屑","1 茶匙香草精","1 茶匙可可粉"],"instructions":["将杏仁粉放入煎锅，中火翻炒约 3 分钟，直到金黄。","把炒香的杏仁粉与 1 1/2 汤匙赤藓糖醇、肉桂粉、盐和浓缩咖啡混合。","将杏仁混合物分装到 6 个食用杯中。","混合酸奶、马斯卡彭奶酪、剩余赤藓糖醇、朗姆酒、橙皮屑和香草精。","把奶油混合物舀在杏仁底上，食用前撒上可可粉。"],"nutrition":["140 千卡","14 克碳水化合物","8 克总脂肪","1 克纤维","10 克蛋白质"]},"zh-TW":{"title":"簡易低碳水提拉米蘇","category":"甜點","excerpt":"較輕盈的提拉米蘇風味甜點，含杏仁碎、希臘酸奶、馬斯卡彭奶酪、咖啡和可可。","tags":["甜點","低碳水","享受型小點"],"prepTime":"15 分鐘","cookTime":"3 分鐘","servings":"6","diabetesNote":"低碳水甜點仍可能影響血糖；份量和食用時機都很重要。","carbAwareness":"建議作爲計劃餐食的一部分享用，而不是空腹單獨食用。","ingredients":["1/2 杯杏仁粉","1/4 杯另加 1 1/2 湯匙赤蘚糖醇或其他代糖，分開使用","1 茶匙肉桂粉","1/4 茶匙鹽","1 湯匙濃縮咖啡或濃咖啡","2 杯原味脫脂希臘酸奶","3 湯匙馬斯卡彭奶酪","1 湯匙黑朗姆酒","2 茶匙橙皮屑","1 茶匙香草精","1 茶匙可可粉"],"instructions":["將杏仁粉放入煎鍋，中火翻炒約 3 分鐘，直到金黃。","把炒香的杏仁粉與 1 1/2 湯匙赤蘚糖醇、肉桂粉、鹽和濃縮咖啡混合。","將杏仁混合物分裝到 6 個食用杯中。","混合酸奶、馬斯卡彭奶酪、剩餘赤蘚糖醇、朗姆酒、橙皮屑和香草精。","把奶油混合物舀在杏仁底上，食用前撒上可可粉。"],"nutrition":["140 千卡","14 克碳水化合物","8 克總脂肪","1 克纖維","10 克蛋白質"]},"es":{"title":"Tiramisú fácil bajo en carbohidratos","category":"Postre","excerpt":"Un postre ligero estilo tiramisú con crumble de almendra, yogur griego, mascarpone, café y cacao.","tags":["Postre","Bajo en carbohidratos","Antojo"],"prepTime":"15 min","cookTime":"3 min","servings":"6","diabetesNote":"Los postres con menos carbohidratos aún pueden afectar la glucosa; la porción y el momento importan.","carbAwareness":"Disfrútelo como parte de una comida planificada, no solo con el estómago vacío.","ingredients":["1/2 taza de harina de almendra","1/4 taza más 1 1/2 cucharadas de eritritol u otro sustituto de azúcar, dividido","1 cucharadita de canela molida","1/4 cucharadita de sal","1 cucharada de espresso o café fuerte","2 tazas de yogur griego natural sin grasa","3 cucharadas de queso mascarpone","1 cucharada de ron oscuro","2 cucharaditas de ralladura de naranja","1 cucharadita de extracto de vainilla","1 cucharadita de cacao en polvo"],"instructions":["Tueste la harina de almendra en una sartén a fuego medio durante 3 minutos o hasta que esté dorada.","Mezcle la harina de almendra tostada con 1 1/2 cucharadas de eritritol, canela, sal y espresso.","Divida la mezcla de almendra entre 6 vasos para servir.","Mezcle el yogur, el mascarpone, el eritritol restante, el ron, la ralladura de naranja y la vainilla.","Coloque la crema sobre la base de almendra y espolvoree cacao antes de servir."],"nutrition":["140 calorías","14 g de carbohidratos","8 g de grasa total","1 g de fibra","10 g de proteína"]}}}','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z','2026-10-28T00:00:00.000Z');
INSERT OR IGNORE INTO recipes (id,slug,draft_json,published_json,published_at,created_at,updated_at) VALUES ('recipe_import_mediterranean-zucchini','mediterranean-zucchini','{"image":"/recipe-covers/mediterranean-zucchini.webp","originalCard":"/recipe-cards/mediterranean-zucchini-card.webp","date":"2025-01-13","translations":{"en":{"title":"Mediterranean Zucchini","category":"Vegetable side","excerpt":"Baked zucchini with olive oil, lemon zest, herbs, red pepper flakes, and Parmesan.","tags":["Heart Healthy","Low Carb","Side"],"prepTime":"10 min","cookTime":"20 min","servings":"4","diabetesNote":"Non-starchy vegetables add volume, fiber, and color with fewer carbohydrates.","carbAwareness":"Use this to fill half your plate.","ingredients":["2 zucchini, 5-6 oz each, cut in half lengthwise","2 tsp olive oil","1/2 tsp lemon zest","1/2 tsp dried basil","1/2 tsp dried oregano","1/8 tsp crushed red pepper flakes","1/8 tsp salt","4 tsp grated Parmesan cheese"],"instructions":["Preheat oven to 400 F.","Place zucchini cut side up on a baking sheet and drizzle with oil.","Mix lemon zest, basil, oregano, red pepper flakes, and salt.","Sprinkle herb mixture over zucchini.","Bake 20 minutes or until just tender.","Sprinkle each half with 1 tsp Parmesan and let stand 5 minutes before serving."],"nutrition":["40 calories","3g carbohydrates","3g total fat","1g fiber","1g protein"]},"zh-CN":{"title":"地中海风味西葫芦","category":"蔬菜配菜","excerpt":"烤西葫芦搭配橄榄油、柠檬皮屑、香草、红椒碎和帕玛森奶酪。","tags":["护心","低碳水","配菜"],"prepTime":"10 分钟","cookTime":"20 分钟","servings":"4","diabetesNote":"非淀粉类蔬菜可增加餐盘体积、纤维和色彩，同时碳水较少。","carbAwareness":"可用这道菜填满半个餐盘。","ingredients":["2 根西葫芦，每根约 140-170 克，纵向切半","2 茶匙橄榄油","1/2 茶匙柠檬皮屑","1/2 茶匙干罗勒","1/2 茶匙干牛至","1/8 茶匙红椒碎","1/8 茶匙盐","4 茶匙帕玛森奶酪碎"],"instructions":["烤箱预热至约 200 摄氏度。","将西葫芦切面朝上放在烤盘中，淋上油。","混合柠檬皮屑、罗勒、牛至、红椒碎和盐。","把香草混合物撒在西葫芦上。","烤 20 分钟，或直到刚好变软。","每半根西葫芦撒 1 茶匙帕玛森奶酪，静置 5 分钟后食用。"],"nutrition":["40 千卡","3 克碳水化合物","3 克总脂肪","1 克纤维","1 克蛋白质"]},"zh-TW":{"title":"地中海風味西葫蘆","category":"蔬菜配菜","excerpt":"烤西葫蘆搭配橄欖油、檸檬皮屑、香草、紅椒碎和帕瑪森奶酪。","tags":["護心","低碳水","配菜"],"prepTime":"10 分鐘","cookTime":"20 分鐘","servings":"4","diabetesNote":"非澱粉類蔬菜可增加餐盤體積、纖維和色彩，同時碳水較少。","carbAwareness":"可用這道菜填滿半個餐盤。","ingredients":["2 根西葫蘆，每根約 140-170 克，縱向切半","2 茶匙橄欖油","1/2 茶匙檸檬皮屑","1/2 茶匙幹羅勒","1/2 茶匙幹牛至","1/8 茶匙紅椒碎","1/8 茶匙鹽","4 茶匙帕瑪森奶酪碎"],"instructions":["烤箱預熱至約 200 攝氏度。","將西葫蘆切面朝上放在烤盤中，淋上油。","混合檸檬皮屑、羅勒、牛至、紅椒碎和鹽。","把香草混合物撒在西葫蘆上。","烤 20 分鐘，或直到剛好變軟。","每半根西葫蘆撒 1 茶匙帕瑪森奶酪，靜置 5 分鐘後食用。"],"nutrition":["40 千卡","3 克碳水化合物","3 克總脂肪","1 克纖維","1 克蛋白質"]},"es":{"title":"Zucchini mediterráneo","category":"Acompañamiento de verduras","excerpt":"Zucchini al horno con aceite de oliva, ralladura de limón, hierbas, hojuelas de chile rojo y Parmesan.","tags":["Salud del corazón","Baja en carbohidratos","Acompañamiento"],"prepTime":"10 min","cookTime":"20 min","servings":"4","diabetesNote":"Las verduras sin almidón aportan volumen, fibra y color con menos carbohidratos.","carbAwareness":"Úselo para llenar la mitad de su plato.","ingredients":["2 zucchini, de 5 a 6 oz cada uno, cortados por la mitad a lo largo","2 cucharaditas de aceite de oliva","1/2 cucharadita de ralladura de limón","1/2 cucharadita de albahaca seca","1/2 cucharadita de orégano seco","1/8 cucharadita de hojuelas de chile rojo trituradas","1/8 cucharadita de sal","4 cucharaditas de queso Parmesan rallado"],"instructions":["Precaliente el horno a 400 F.","Coloque el zucchini con el lado cortado hacia arriba en una bandeja y rocíe con aceite.","Mezcle la ralladura de limón, la albahaca, el orégano, las hojuelas de chile rojo y la sal.","Espolvoree la mezcla de hierbas sobre el zucchini.","Hornee 20 minutos o hasta que esté apenas tierno.","Espolvoree cada mitad con 1 cucharadita de Parmesan y deje reposar 5 minutos antes de servir."],"nutrition":["40 calorías","3 g de carbohidratos","3 g de grasa total","1 g de fibra","1 g de proteína"]}}}','{"image":"/recipe-covers/mediterranean-zucchini.webp","originalCard":"/recipe-cards/mediterranea